window.__SUM[17]={"LR000003":{"pair":"ADAM10 -> EPHA3","headline":"ADAM10 associates with EphA3 and sheds its ephrin ligand; association is supported by two papers but is an enzyme-receptor partnership.","interaction_type":"direct binding","direction_and_effect":"ADAM10 constitutively associates with EphA3, and the EphA3/ephrin-A5 complex creates a recognition motif for the ADAM10 cysteine-rich domain [PMID:16239146]. Activated EphA3 extends its intracellular domain and facilitates productive association with ADAM10, enabling ephrin shedding in trans [PMID:19823572].","molecular_requirements":"Co-immunoprecipitation showed robust ADAM10 binding to an EphA3 mutant lacking the whole intracellular domain, so extracellular domains suffice for association (results in this paper) [PMID:19823572]. Shedding depends on EphA3 conformation rather than kinase activity [PMID:19823572].","affinity_potency":[],"species_and_systems":"Human proteins in curator rows; HEK293T cells with EphA3 and ADAM10 constructs [PMID:19823572].","localisation_and_range":"EPHA3 flagged both secreted and transmembrane; ADAM10 flagged not secreted [flag]. Shedding acts in trans between cells [PMID:16239146].","caveats":"Both papers read mainly as abstracts; one has full-text excerpts. IntAct lists a co-immunoprecipitation record [DB:IntAct]. The mutual effect on EphA3 signalling is not reported.","key_references":[{"PMID":"19823572","why":"EphA3 conformation controls ADAM10 association and shedding"},{"PMID":"16239146","why":"ADAM10 cysteine-rich domain recognises EphA3/ephrin-A5 complex"}],"covers":["LR000003","LR003553"]},"LR000012":{"pair":"ADAM17 -> ITGA5","headline":"ADAM17 supports cell adhesion via integrin alpha5beta1 (functional, human HeLa); IntAct lists ADAM17-ITGB1 related records.","interaction_type":"functional only","direction_and_effect":"Recombinant ADAM-17 extracellular fragments support cell adhesion through alpha5beta1 in a trans orientation; adhesion was sensitive to RGD peptides and EDTA, indicating a ligand-receptor relationship via the alpha5beta1 ligand-binding pocket [PMID:14970227].","molecular_requirements":"The integrin-binding site within ADAM-17 maps to the disintegrin/cysteine-rich region [PMID:14970227]. The result concerns alpha5beta1 as a heterodimer; ITGA5 alone is not tested separately in our evidence.","affinity_potency":[],"species_and_systems":"Human cell lines and HeLa cells with recombinant human ADAM-17 fragments [PMID:14970227].","localisation_and_range":"Trans-adhesion with recombinant ectodomain; ADAM17 and alpha5beta1 also co-localise in HeLa membrane ruffles and focal adhesions, suggestive of a cis orientation [PMID:14970227]. ADAM17 is flagged non-secreted [flag].","caveats":"Abstract read only; labelled functional rather than direct binding. IntAct holds two records (co-IP, ELISA) listing the pair, with PMIDs 30455686 and 22413019 [DB:IntAct]; those papers were not read by curators here.","key_references":[{"PMID":"14970227","why":"ADAM-17 supports alpha5beta1-dependent adhesion, RGD/EDTA sensitive"}],"covers":["LR000012","LR003562"]},"LR000021":{"pair":"ADAM9 -> ITGA3","headline":"ADAM9 disintegrin domain captures integrin alpha3 from human renal lysate; abstract only.","interaction_type":"direct binding","direction_and_effect":"Immobilised GST-disintegrin domain with renal cortical lysates specifically recovered the alpha3, alpha6, alphav and beta1 chains; anti-alpha3 antibody also blocked HEK-293 adhesion [PMID:15361064].","molecular_requirements":"Alpha3 is recovered together with beta1 [PMID:15361064]; the disintegrin domain is responsible for competitive inhibition of cell-matrix binding [PMID:15361064].","affinity_potency":[],"species_and_systems":"Human HEK-293 cells and renal cortical lysate; recombinant GST-disintegrin [PMID:15361064]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM9 flagged secreted [flag]; basolateral renal tubular expression per the paper [PMID:15361064].","caveats":"Abstract read only; affinity capture from lysate, so not necessarily direct.","key_references":[{"PMID":"15361064","why":"GST-disintegrin pull-down recovers alpha3"}],"covers":["LR000021","LR003571"]},"LR000030":{"pair":"ADIPOQ -> ADIPOR1","headline":"AdipoR1 was expression-cloned as an adiponectin receptor; one abstract-only paper plus Reactome and UniProt records.","interaction_type":"direct binding","direction_and_effect":"AdipoR1/R2 overexpression or siRNA suppression supports a role as receptors for globular and full-length adiponectin, mediating increased AMP kinase and PPAR-alpha ligand activities, fatty-acid oxidation and glucose uptake [PMID:12802337]. Activating effect.","molecular_requirements":"Reactome lists an ADIPOQ trimer bound to ADIPOR dimers [DB:Reactome]. Whether one receptor chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cDNAs and cells per curator label [PMID:12802337]. Mouse pair is non-inferred, human pair is ortholog-inferred.","localisation_and_range":"Adiponectin is flagged secreted [flag], so hormonal/endocrine action is implied; the receptor is plasma membrane per Reactome [DB:Reactome].","caveats":"Evidence is functional (gain and loss of function), not a direct binding measurement, in the abstract [PMID:12802337]. Paper covers both AdipoR1 and AdipoR2, not separated. No affinity reported.","key_references":[{"PMID":"12802337","why":"expression cloning of AdipoR1 and AdipoR2"}],"covers":["LR000030","LR003580"]},"LR007947":{"pair":"ALB -> B2M:FCGRT","headline":"Albumin binding to FcRn is supported by database records only (structures, SPR, co-purification); no verified paper for the complex entity.","interaction_type":"database-asserted only","direction_and_effect":"Albumin binds FCGRT. UniProt states the interaction regulates ALB homeostasis [DB:UniProt]. Curated crystal structures include ALB with FcRn [DB:PDB 4N0F] and a high-affinity albumin variant [DB:PDB 4K71]; IntAct lists SPR [DB:IntAct P55899-P02768].","molecular_requirements":"The receptor is the B2M:FCGRT complex, but the records name ALB with FCGRT. PDB records list a further chain, P61769, which the dossier does not name [DB:PDB 4K71]. Subunit requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; BioGRID records co-purification and reconstituted complex [DB:BioGRID 276735, DB:BioGRID 276740]; structures are of the human complex [DB:PDB 4N0F].","localisation_and_range":"ALB flagged secreted; receptor flagged transmembrane [flag].","caveats":"No curator-verified paper; only review_only and different_entity rows. No affinity in our evidence.","key_references":[],"covers":["LR007947"]},"LR002100":{"pair":"ANG -> EGFR","headline":"Direct binding of ANG to EGFR with a measured Kd, activating EGFR, from one study in human cells.","interaction_type":"direct binding","direction_and_effect":"ANG acts as an EGFR agonist: it induced EGFR phosphorylation, downstream signalling and EGFR dimerization, and cetuximab or erlotinib/gefitinib blocked ANG-mediated activation [PMID:29606349].","molecular_requirements":"Purified ANG formed a complex with recombinant EGFR in cross-linking assays. ANG C-terminus (residues 74-123) and Q93 are needed for binding; EGFR domains I and III are involved, and the epitope partly overlaps the EGF binding region. Binding is independent of ANG catalytic activity [PMID:29606349].","affinity_potency":[{"value":"Kd 41.6 nM","assay":"binding of ANG to EGFR (estimated Kd)","system":"human ANG and EGFR","cite":"PMID:29606349"}],"species_and_systems":"Human ANG and human EGFR; cell lines and recombinant protein [PMID:29606349]. The mouse pair is projected from human evidence.","localisation_and_range":"ANG is flagged as secreted and EGFR as transmembrane [flag]; ANG binds the EGFR extracellular domain [PMID:29606349].","caveats":"Single paper; the curator read the abstract and full-text excerpts. The paper says a co-crystal structure is still worth pursuing, so no structural proof of contact [PMID:29606349]. No databases support this pair. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"29606349","why":"ANG binds and activates EGFR; Kd, binding determinants"}],"covers":["LR002100","LR005426"]},"LR007938":{"pair":"ARTN -> GFRA3:RET","headline":"ARTN binds GFRA3 directly (crystal structure) and signals through the GFRA3-RET complex; well supported, with the RET step shown functionally.","interaction_type":"direct binding","direction_and_effect":"ARTN is the ligand and acts as an agonist: it was identified as the ligand of the former orphan receptor GFRalpha3-RET and supports neuron survival in culture [PMID:9883723]. A 1.92 A crystal structure shows the ARTN-GFRalpha3 complex, the initiating step toward a ternary complex with RET [PMID:16765900]. UniProt describes a 2:2:2 ARTN:GFRA3:RET complex [DB:UniProt].","molecular_requirements":"Receptor is the two-chain complex GFRA3 (ligand-binding, GPI-type co-receptor role) plus RET (signalling chain). Cellular chimera studies implicate composite interfaces for RET recruitment and dimerization [PMID:16765900]. ARTN can also activate GFRalpha1-RET, so GFRA3 is the preferred, not exclusive, partner [PMID:9883723]. Direct ARTN contact was structurally shown for GFRA3, not for RET, in the abstract-level evidence [PMID:16765900].","affinity_potency":[],"species_and_systems":"Human ligand and receptor recorded for both papers; structure from purified proteins by X-ray crystallography [PMID:16765900]; the 1998 paper used neurons in culture [PMID:9883723]. Both read as abstracts only.","localisation_and_range":"ARTN is flagged secreted and the receptor complex as transmembrane receptor [flag]; implies paracrine signalling, not tested in our evidence.","caveats":"Both papers were read as abstracts only. One further paper was judged unresolvable. No affinity value in our evidence. Other structures and IntAct records (electron microscopy) exist [DB:PDB 6Q2S] [DB:IntAct].","key_references":[{"PMID":"16765900","why":"1.92 A crystal structure of ARTN-GFRalpha3 complex"},{"PMID":"9883723","why":"Identified ARTN as ligand of GFRalpha3-RET; neuron survival"}],"covers":["LR007938"]},"LR009684":{"pair":"B2M -> CD1B","headline":"B2M and CD1B are recorded as a structurally resolved complex; no verified paper, database evidence only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; Reactome records a CD1B:B2M complex [DB:Reactome R-HSA-8848855] and PDB holds structures such as CD1b with GM2 ganglioside [DB:PDB 1GZP].","molecular_requirements":"IntAct lists direct interaction by x-ray crystallography [DB:IntAct EBI-1037979] and coimmunoprecipitation entries [DB:IntAct EBI-21693940]; 55 PDB records [DB:PDB 1GZP].","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (IntAct, PDB, Reactome). Judged row was classified different_entity.","key_references":[],"covers":["LR009684"]},"LR009675":{"pair":"B2M -> CD247","headline":"B2M and CD247 co-occur only as chains in TCR-CD3 and peptide-MHC cryo-EM structures; no direct contact is shown in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. PDB entries are TCR-CD3 engaging peptide-MHC I [DB:PDB 7PHR] and a TCR-CD3 with HLA-A2 MAGEA4 peptide [DB:PDB 8ES8].","molecular_requirements":"Structures contain a B2M chain and a CD247 chain within a larger assembly (6 PDB records) [DB:PDB 7PHR]; whether B2M contacts CD247 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (PDB only (6 records)). The judged row was classified review_only.","key_references":[],"covers":["LR009675"]},"LR000102":{"pair":"BGN -> TLR2","headline":"Biglycan is an endogenous TLR2 agonist in macrophages, shown genetically, with a microscale thermophoresis record in IntAct.","interaction_type":"functional only","direction_and_effect":"Biglycan acts in macrophages as an endogenous ligand of TLR4 and TLR2, activating p38, ERK and NF-kappaB and stimulating TNF-alpha and MIP-2 [PMID:16025156]. Effects were reduced in TLR4-mutant, TLR2-/- and MyD88-/- macrophages and abolished in TLR2-/-/TLR4-mutant cells [PMID:16025156]. Biglycan-null mice had a survival benefit in LPS- or zymosan-induced sepsis [PMID:16025156]. IntAct lists a microscale thermophoresis record P21810-O60603 citing PMID 24480070 [DB:IntAct].","molecular_requirements":"TLR2 and TLR4 each contribute, with complete loss only in the double mutant; MyD88 is needed [PMID:16025156].","affinity_potency":[],"species_and_systems":"Mouse macrophages and mice (genetic models); human and mouse pairs listed [PMID:16025156]. Abstract-only read.","localisation_and_range":"Biglycan released from the matrix or from macrophages acts as a soluble signal [PMID:16025156]; secreted flag [flag].","caveats":"Abstract-only; evidence is functional, with no affinity values in our evidence. The two TLRs are not separated except by the genetic series; the IntAct record gives no values here.","key_references":[{"PMID":"16025156","why":"biglycan signals through TLR4 and TLR2 in macrophages"}],"covers":["LR000102","LR003651"]},"LR000120":{"pair":"BMP2 -> BMPR1B","headline":"BMP2 binds the type I receptor BMPR1B (ALK6) directly; well supported by SPR, cell cross-linking and cloning.","interaction_type":"direct binding","direction_and_effect":"BMP2 is the ligand and BMPR1B a type I receptor; BMP2 activity was competitively inhibited by the BMPR1B ectodomain in C2C12 cells [PMID:19956691]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"BMP2 formed heteromeric complexes with type II receptors ActRII and ActRIIB in P19 cells, alongside ALK3 and ALK6 binding [PMID:9748228]. Endoglin binding of BMP-2 required the type I receptors ALK3/ALK6 [PMID:9872992]. Whether BMPR1B alone suffices for signalling is not reported in our evidence.","affinity_potency":[{"value":"apparent KD 2.7 nM","assay":"SPR, BMP2 over immobilized receptor ectodomain","system":"recombinant ligand and receptor ectodomains","cite":"PMID:19735544"}],"species_and_systems":"Binding data come from recombinant proteins (SPR) and P19 embryonic carcinoma cells [PMID:19735544][PMID:9748228]; the receptor was cloned and shown to bind BMP-2 in an early study [PMID:7811286]. The dossier covers human and mouse pairs; the species of each experiment is mostly not reported in our evidence.","localisation_and_range":"BMP2 is flagged secreted [flag]; ligand acts on cell-surface receptors (paracrine).","caveats":"Two of the supporting papers were read only as abstracts [PMID:9872992][PMID:7811286]. The endoglin paper concerns binding within an accessory-protein complex.","key_references":[{"PMID":"19735544","why":"SPR affinities of BMP2 for BMPR-IB, full text"},{"PMID":"9748228","why":"[125I]BMP2 affinity labelling shows ALK6 binding and type II receptor complexes"},{"PMID":"19956691","why":"BMPR1B ectodomain competitively inhibits BMP2 activity"}],"covers":["LR000120","LR003669"]},"LR005499":{"pair":"BMP6 -> RGMA","headline":"Direct SPR binding of BMP6 to RGMA, Kd 55 nM, in one 2012 paper; lowest affinity of the three RGMs for BMP6.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance measured binding of RGMA to BMP6 with K(D) 55 nM; curated effect is agonist [PMID:23029472].","molecular_requirements":"RGM proteins are described as BMP co-receptors; the paper measured RGM protein binding to BMP ligands, and receptor chains needed for signalling are not reported in our evidence [PMID:23029472].","affinity_potency":[{"value":"Kd 55 nM","assay":"surface plasmon resonance","system":"recombinant RGM proteins with BMP ligands","cite":"PMID:23029472"}],"species_and_systems":"Recombinant human proteins per curator; abstract-level curation with full-text excerpts describing SPR (mean of 4-9 experiments) [PMID:23029472]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor is flagged as secreted [flag]; localisation is otherwise not reported in our evidence.","caveats":"Affinity data are from an in vitro SPR matrix; no cellular signalling result for this pair is reported in our evidence. Compared with other RGMs: HJV 8.1, RGMB 28, RGMA 55 nM for BMP6 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGM proteins for BMP ligands"}],"covers":["LR002185","LR005499"]},"LR006786":{"pair":"BMP7 -> ACVRL1","headline":"No paper supports this pair; only a GtoPdb record, and the BioGRID records cited concern BMPR1B.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP7 -> ACVRL1 as agonist [DB:GtoPdb]. No curator-verified paper in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Two papers were abstract_insufficient and one was a different_entity match, none confirmed. The BioGRID examples shown are BMP7-BMPR1B reconstituted complexes, not ACVRL1 [DB:BioGRID].","key_references":[],"covers":["LR006786"]},"LR003699":{"pair":"BTLA -> TNFRSF14","headline":"Well supported direct binding between BTLA and HVEM (TNFRSF14), with a structure and inhibitory signalling; papers describe HVEM as the ligand acting on BTLA.","interaction_type":"direct binding","direction_and_effect":"Binding competition and mutagenesis place the BTLA site on HVEM cysteine-rich domain 1 [PMID:16131544]. BTLA did not bind B7x and HVEM was identified as the unique BTLA ligand; HVEM engagement induced BTLA tyrosine phosphorylation and SHP-2 association and repressed T cell proliferation [PMID:15568026]. In mouse, HVEM engaging BTLA on T cells reduced TCR signalling and CD40L mobilisation, restraining germinal centre B cell participation [PMID:31204070]. The effect is inhibitory.","molecular_requirements":"The BTLA site is on HVEM CRD1, distinct from the LIGHT site [PMID:16131544, PMID:15568026]. A BTLA-HVEM complex structure exists [DB:PDB 2AW2]. No further subunit requirements reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant/cell binding work [PMID:16131544, PMID:15568026]; mouse in vivo B cell/T cell work [PMID:31204070]. Both entries are mouse and human, not inferred.","localisation_and_range":"Both partners are annotated as transmembrane [flag]. UniProt notes BTLA may interact in cis or in trans [DB:UniProt].","caveats":"The two binding papers were read as abstracts only. Herpesvirus gD blocks both BTLA and LIGHT binding to HVEM, and the CMV UL144 mimic binds BTLA [PMID:16131544]. No affinity values reported in our evidence.","key_references":[{"PMID":"15568026","why":"identifies HVEM as the BTLA partner, binds CRD1, SHP-2 signalling"},{"PMID":"16131544","why":"BTLA binding site mapped on HVEM CRD1 by competition and mutagenesis"},{"PMID":"31204070","why":"mouse in vivo: HVEM signals via BTLA on T cells"}],"covers":["LR000150","LR003699"]},"LR009378":{"pair":"CALM1 -> CACNA1C","headline":"Calmodulin binds the CaV1.2 (CACNA1C) IQ domain, shown by crystal structures; this is a regulator-channel interaction.","interaction_type":"direct binding","direction_and_effect":"A 2.0 A crystal structure of the CaV1.2 IQ domain-Ca/CaM complex exists [DB:PDB 2BE6], with further calmodulin/IQ structures [DB:PDB 2F3Y]. IntAct records a physical association by pull down [DB:IntAct EBI-1184894]. UniProt says calmodulin or CABP1 binding at the same sites has opposite effects on channel function [DB:UniProt].","molecular_requirements":"Binding is via the IQ domain with Ca/CaM [DB:PDB 2BE6].","affinity_potency":[],"species_and_systems":"Human proteins; structures X-ray and pull-down, from databases.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. One row was different_entity; 28 structures exist but only 5 are shown.","key_references":[],"covers":["LR009378"]},"LR008469":{"pair":"CALM2 -> PDE1B","headline":"CALM2 activates PDE1B according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM2 as an activator of PDE1B (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. One judged paper was review-only. Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008469"]},"LR000201":{"pair":"CCL16 -> CCR2","headline":"CCL16 is a low-affinity functional ligand of human CCR2 in one panel study; database records agree.","interaction_type":"direct binding","direction_and_effect":"CCL16 induced calcium mobilisation and chemotaxis via CCR2 at relatively high concentrations and bound with relatively low affinity [PMID:11470772]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L1.2 pre-B cells stably expressing human receptors; human ligand; abstract-only [PMID:11470772].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Single paper, low affinity, no numeric value. Reactome lists CCR1, 2 and 8 [DB:Reactome].","key_references":[{"PMID":"11470772","why":"CCL16 low-affinity CCR2 binding and signalling"}],"covers":["LR000201"]},"LR000210":{"pair":"CCL19 -> CCR7","headline":"Strongly supported direct binding and agonism of CCL19 at CCR7 with picomolar-range affinity and in vivo function.","interaction_type":"direct binding","direction_and_effect":"CCL19 is an agonist: it induced calcium mobilization and chemotaxis in CCR7 (EBI1) transfected cells and HUT78 cells [PMID:9153236]; ELC and SLC were essentially equivalent via CCR7 [PMID:9507024]; in mice, intracutaneous ELC restored T cell trafficking to lymph nodes in plt/plt mice [PMID:11342595].","molecular_requirements":"CCR7 alone sufficed in transfected cells [PMID:9153236][PMID:9507024]; no additional subunits reported in our evidence.","affinity_potency":[{"value":"Kd ~100 pM","assay":"ligand binding","system":"CCR-7-expressing HEK-293E cells","cite":"PMID:10512740"}],"species_and_systems":"Human ligand and receptor in vitro [PMID:9153236][PMID:10512740]; mouse in vivo for the plt/plt rescue [PMID:11342595]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag]. Perivascular ELC is transcytosed to high endothelial venule surfaces [PMID:11342595].","caveats":"All papers read as abstract only except 11342595 (full text), whose CCR7 pairing is background and whose own contribution is transcytosis. GtoPdb records the interaction as agonist [DB:GtoPdb].","key_references":[{"PMID":"9153236","why":"Identifies CCL19 binding specifically to CCR7, calcium and chemotaxis"},{"PMID":"10512740","why":"High-affinity binding, Kd in the 100 pM range"},{"PMID":"11342595","why":"In vivo T cell homing rescue in mice"}],"covers":["LR000210","LR003738"]},"LR006795":{"pair":"CCL19 -> CXCR3","headline":"Weak, low-affinity competition binding only, from a table row in one paper; CCL19 is not named in the abstract.","interaction_type":"direct binding","direction_and_effect":"The curated table row shows MIP-3beta competing for 125I-IP10 binding to CXCR3 with Ki 1300 nM; the curator recorded 'full agonist', but the dossier shows no CCL19 activation data [PMID:9660793]. GtoPdb lists a full agonist record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 1300 nM","assay":"competition vs 125I-IP10","system":"CHO cells expressing human CXCR3","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and receptor; CHO cells expressing human CXCR3 [PMID:9660793].","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Very low affinity relative to IP10 (Ki 0.14 nM) and MIG (4.9 nM) [PMID:9660793]. The paper abstract does not mention CCL19; the row is a table entry, the quote is unverified. The paper calls eotaxin a possible antagonist, not CCL19. Three other judgements were different_entity and three abstract_insufficient.","key_references":[{"PMID":"9660793","why":"CXCR3 pharmacology; Ki 1300 nM row"}],"covers":["LR006795"]},"LR003789":{"pair":"CD14 -> ITGA4","headline":"Direct solid-phase binding of CD14-Fc to integrin alpha4beta1 reported in one abstract-read paper; ITGA4 is one chain of the receptor.","interaction_type":"direct binding","direction_and_effect":"CD14-Fc bound affinity-purified alpha4beta1 in a dose-dependent manner and Jurkat cells adhered to CD14-Fc via alpha4beta1 [PMID:17274987].","molecular_requirements":"Receptor is the alpha4beta1 heterodimer; re-expressing the alpha4 subunit in alpha4beta1-negative K562 cells conferred adhesion [PMID:17274987].","affinity_potency":[],"species_and_systems":"Human cells and recombinant CD14-Fc (Jurkat, K562 transfectants); the mouse pair is ortholog-inferred, not tested [PMID:17274987].","localisation_and_range":"CD14 is flagged secreted and a receptor [flag]; it is described as GPI-linked on the cell surface in the abstract, so juxtacrine adhesion is the tested setting [PMID:17274987].","caveats":"Single paper, read as abstract only. No database records. No affinity reported.","key_references":[{"PMID":"17274987","why":"CD14-Fc binds alpha4beta1 in solid phase; Jurkat adhesion"}],"covers":["LR000279","LR003789"]},"LR008973":{"pair":"CD14 -> ITGB2","headline":"Supported only by Reactome records of an LPS:CD14:CR3 complex; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome describes a binding reaction in which CD14:LPS binds CR3 and a complex LPS:CD14:CR3 at the plasma membrane [DB:Reactome R-HSA-2559439][DB:Reactome R-HSA-2559438].","molecular_requirements":"The Reactome complex is with LPS bound to CD14 and CR3 (an integrin complex); a requirement for other subunits is not reported in our evidence [DB:Reactome R-HSA-2559438].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence; the records cite PMIDs 10201950, 16751103, 2462607 and 3537192 but no verified paper is in the dossier [DB:Reactome].","localisation_and_range":"CD14 is flagged secreted and a receptor, ITGB2 as a receptor [flag].","caveats":"No curator-verified paper (outcome counts: review_only 1, different_entity 1, abstract_insufficient 2). The record is LPS-dependent and may not represent direct CD14-ITGB2 binding.","key_references":[],"covers":["LR008973"]},"LR005589":{"pair":"CD40LG -> ITGAV","headline":"CD40L binds integrin alphavbeta3 in two papers (abstract-only) and UniProt; ITGAV is a chain of that receptor.","interaction_type":"direct binding","direction_and_effect":"Integrin alphavbeta3 bound CD40L in a KGD-independent manner, suggesting a new CD40L receptor; integrin-binding-defective CD40L mutants were defective in NF-kB and B cell activation and suppressed wild-type CD40L signalling while still binding CD40 [PMID:31331973]. Soluble CD40L activated soluble alphavbeta3, alpha5beta1 and alpha4beta1 in cell-free conditions, and cell-surface integrins in CD40-negative CHO cells [PMID:33571526]. UniProt lists ITGAV:ITGB3 as a receptor for CD40LG [DB:UniProt].","molecular_requirements":"Evidence is for the alphav:beta3 heterodimer; ITGAV alone is not tested. Binding to a site-2 cyclic peptide and docking place the site-2 residues outside the trimer interface [PMID:33571526].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curators; recombinant and cell-line systems (CHO cells) [PMID:31331973][PMID:33571526]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; the studies used soluble CD40L [PMID:33571526].","caveats":"Both papers read as abstracts only; no affinity reported. Two more confirmed papers are not shown.","key_references":[{"PMID":"31331973","why":"alphavbeta3 binds CD40L; integrin-binding-defective mutants"},{"PMID":"33571526","why":"Soluble CD40L activates alphavbeta3 and other integrins"}],"covers":["LR002290","LR005589"]},"LR003798":{"pair":"CD70 -> CD27","headline":"CD70 is the established ligand of CD27, supported by cloning, antibody competition, binding databases and functional studies, mostly in human cells.","interaction_type":"direct binding","direction_and_effect":"CD70 engagement of CD27 is stimulatory in B-cell assays: CD70 transfectants raised IgG, IgM and IgA synthesis with IL-10, blocked by anti-CD70 [PMID:9767422], and raised IgE synthesis with IL-4 plus anti-CD40 [PMID:9862673]. In haematopoietic progenitors the effect was inhibitory: CD70 reduced colony-forming potential in vitro and lymphocyte outgrowth in vivo [PMID:15723067]. CD27-transfected cells inhibited T-cell-dependent IgG production, consistent with a decoy-like effect [PMID:7479974]. Stimulatory modulatory effect annotated in the interaction record.","molecular_requirements":"Not reported in our evidence beyond a CD27:CD70 homotrimer complex and a PDB structure with one chain of each [DB:Reactome R-HSA-5669095] [DB:PDB 7KX0]. Anti-CD70 antibodies interfered with CD27L antibody binding on transfected mouse fibroblasts [PMID:8186199].","affinity_potency":[],"species_and_systems":"Human cells throughout the papers, using mouse pre-B or fibroblast cells and monkey kidney cells as transfection hosts [PMID:7479974] [PMID:8120384]; the progenitor study is listed as human on both sides [PMID:15723067]. A mouse pair is also in the dossier.","localisation_and_range":"CD70 is a type II transmembrane protein [PMID:8120384], so signalling is by cell contact; the annotation flags list it as neither secreted nor transmembrane [flag]. Cell-to-cell contact is stated for CD27/CD70 in B cells [PMID:9767422].","caveats":"All papers were read as abstracts only. No affinity value is reported in our evidence. Binding is supported by BioGRID, IntAct, GtoPdb, Reactome and PDB records [DB:BioGRID] [DB:IntAct] [DB:PDB 7KX0] but the GtoPdb record gives no action or affinity [DB:GtoPdb]. Effect depends on context (stimulatory versus inhibitory).","key_references":[{"PMID":"8120384","why":"Expression cloning shows CD70 is identical to the CD27 ligand"},{"PMID":"8186199","why":"Antibody competition shows CD70 is the CD27 ligand"},{"PMID":"15723067","why":"CD70 stimulation of CD27+ progenitors is inhibitory"}],"covers":["LR000289","LR003798"]},"LR005598":{"pair":"CDH1 -> CDH1","headline":"E-cadherin homophilic binding is well established; ligation transduces growth-inhibitory signals.","interaction_type":"direct binding","direction_and_effect":"Recombinant E-cadherin on microspheres reduced S-phase entry and inhibited EGF-receptor-mediated growth signalling [PMID:17392517]. Database records include reconstituted complex, force spectroscopy and atomic force microscopy [DB:BioGRID] [DB:IntAct].","molecular_requirements":"Growth inhibition required E-cadherin binding to beta-catenin, not p120-catenin or alpha-catenin/actin coupling [PMID:17392517]. Reactome lists a calcium-bound dimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human epithelial cells with recombinant protein [PMID:17392517].","localisation_and_range":"Membrane-bound; juxtacrine homophilic adhesion [flag].","caveats":"Homotypic self-pair, so direction is not meaningful; one paper, abstract only.","key_references":[{"PMID":"17392517","why":"E-cadherin homophilic ligation inhibits growth"}],"covers":["LR002300","LR005598"]},"LR000300":{"pair":"CHAD -> ITGA2","headline":"Chondroadherin binds integrin alpha2beta1 by affinity purification; the evidence is for the heterodimer, not ITGA2 alone.","interaction_type":"direct binding","direction_and_effect":"Annotated stimulatory [flag]. Adhesion of cells to chondroadherin was partially inhibited by an anti-alpha2 antibody (per curator note) and alpha2beta1 was identified as a chondroadherin-binding integrin [PMID:9281592].","molecular_requirements":"The identified receptor is the alpha2beta1 heterodimer; ITGB1 is required as partner in the evidence. Adhesion needed Mg2+ or Mn2+ but not Ca2+ [PMID:9281592].","affinity_potency":[],"species_and_systems":"Affinity purification of cell-surface proteins on chondroadherin-Sepharose; the abstract and excerpts describe bovine chondrocytes, while the curator note describes human fibroblasts [PMID:9281592].","localisation_and_range":"Chondroadherin is a cartilage matrix protein flagged secreted [flag][PMID:9281592]; likely matrix-bound adhesion ligand.","caveats":"Evidence is from a single 1997 paper read as abstract (full-text excerpts available). No affinity reported. Species in the paper is inconsistent between abstract (bovine) and curator note (human).","key_references":[{"PMID":"9281592","why":"Chondroadherin affinity purification identifies alpha2beta1"}],"covers":["LR000300","LR003806"]},"LR009297":{"pair":"CHRM3 -> ARF1","headline":"Only BioGRID records of ARF1-CHRM3 binding; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID records Affinity Capture-Western and Reconstituted Complex from PMID 12799371 [DB:BioGRID]; species of the experiment not reported in our evidence.","localisation_and_range":"CHRM3 flagged receptor [flag]; ARF1 is not flagged as receptor.","caveats":"The curated judgement was a different entity, and ARF1 is not flagged as secreted or as a receptor [flag]. Support rests on database records only.","key_references":[],"covers":["LR009297"]},"LR007965":{"pair":"CNTN1 -> NRCAM","headline":"No curator-confirmed paper; IntAct records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records a solid phase assay and surface plasmon resonance [DB:IntAct]; species not stated.","localisation_and_range":"NRCAM flagged secreted, receptor and transmembrane, CNTN1 flagged transmembrane [flag]; class Adhesion-Adhesion.","caveats":"Three judged papers were all abstract_insufficient; support is from IntAct alone.","key_references":[],"covers":["LR007965"]},"LR006849":{"pair":"COL11A1 -> ITGA1:ITGB1","headline":"Evidence is an abstract-level TNBC study showing COL11A1 binding to ITGB1 only; the named integrin heterodimer is not tested.","interaction_type":"functional only","direction_and_effect":"COL11A1 promoted TNBC metastasis by binding ITGB1, initiating a FAK/YAP cascade; siRNA and rotating magnetic fields suppressed tumour growth and lung metastasis, reversed by an ITGB1 agonist [PMID:41391796].","molecular_requirements":"The paper names the integrin b1 chain only; the alpha subunit (ITGA1) is not reported in our evidence, so the heterodimer assignment is not supported [PMID:41391796].","affinity_potency":[],"species_and_systems":"TNBC cells and an in vivo tumour model; the abstract does not give host species [PMID:41391796].","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; no alpha-subunit-specific data. Other judged papers were review-only, so no primary support for this heterodimer in our evidence [PMID:41391796].","key_references":[{"PMID":"41391796","why":"COL11A1 binding ITGB1 in TNBC"}],"covers":["LR006849"]},"LR006876":{"pair":"COL16A1 -> ITGA2:ITGB1","headline":"Supported only by a UniProt subunit annotation; no primary paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states COL16A1 interacts with integrins ITGA1/ITGB1 and ITGA2/ITGB1 [DB:UniProt Q07092]. Direction and effect are not reported in our evidence.","molecular_requirements":"The annotation names both the ITGA2 and ITGB1 subunits [DB:UniProt Q07092].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt record cites PMID 15165854, which is not among our judged papers [DB:UniProt Q07092].","localisation_and_range":"COL16A1 is annotated secreted and not transmembrane [flag].","caveats":"Database assertion only; judged papers were review-only, so no primary evidence was verified.","key_references":[],"covers":["LR006876"]},"LR005679":{"pair":"COL4A2 -> DDR2","headline":"Direct but weak collagen IV binding and phosphorylation of DDR2 in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Collagen IV bound DDR2 and induced phosphorylation, weaker than fibril-forming collagens [PMID:9659900].","molecular_requirements":"No co-receptor requirement reported in our evidence. COL4A2 is inferred as a chain of the tested commercial type IV collagen, not tested alone [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor, slot-blot and phosphorylation assays; other species are projections [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Commercial type IV collagen is a generic preparation, probably mostly the COL4A1/COL4A2 heterotrimer, so binding cannot be assigned to one chain [PMID:9659900]. Binding was consistently weaker than to fibril-forming collagens [PMID:9659900]. No affinity values reported.","key_references":[{"PMID":"9659900","why":"Collagens as ligands of DDR receptors; type IV weaker than fibrillar"}],"covers":["LR002400","LR005679"]},"LR005697":{"pair":"COL5A1 -> DDR1","headline":"Type V collagen induces DDR1 phosphorylation in a full-text paper; chain not resolved.","interaction_type":"direct binding","direction_and_effect":"Commercial human type V collagen induced DDR1 phosphorylation comparable to the A204-derived ligand [PMID:9659900].","molecular_requirements":"Commercial type V collagen is mostly the COL5A1/COL5A2 heterotrimer and the paper does not resolve single chains [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor; mouse pair is projected [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Chain-level binding not shown; no affinity reported.","key_references":[{"PMID":"9659900","why":"Type V collagen activates DDR1"}],"covers":["LR002418","LR005697"]},"LR006993":{"pair":"COL8A1 -> ITGA1:ITGB1","headline":"COL8A1-ITGB1 interaction reported in colorectal and pancreatic cancer abstracts; the ITGA1 chain itself is not tested.","interaction_type":"functional only","direction_and_effect":"In colorectal cancer, COL8A1 secreted from THBS2+ CAFs is reported to directly interact with ITGB1 on resistant malignant cells, activating PI3K-AKT signaling and promoting EMT and oxaliplatin resistance [PMID:39732719]. In PDAC cells, ITGB1 and DDR1 activation, PI3K/AKT and NF-\u03baB signaling occurred downstream of COL8A1 [PMID:36375776].","molecular_requirements":"Evidence names ITGB1 only; the ITGA1 subunit is not mentioned in our evidence, so the alpha-chain requirement is not reported. Full-text excerpts of PMID:39732719 describe CellChat COL8A1-ITGB1 inference, spatial colocalisation and molecular docking, not subunit requirements [PMID:39732719].","affinity_potency":[],"species_and_systems":"Human colorectal cancer and PDAC cells; both papers read as abstract, with excerpts for PMID:39732719.","localisation_and_range":"Ligand flagged secreted [flag]; CAF-to-tumor-cell paracrine/matrix signaling in the CRC study [PMID:39732719].","caveats":"Complex-level support rests on ITGB1 alone; part of the support is computational (CellChat, spatial colocalisation, docking). Four further rows are review-only.","key_references":[{"PMID":"39732719","why":"COL8A1 from CAFs interacts with ITGB1 in CRC"},{"PMID":"36375776","why":"COL8A1 activates ITGB1/DDR1 signaling in PDAC"}],"covers":["LR006993"]},"LR003879":{"pair":"CRH -> CRHR2","headline":"CRH activates CRHR2 as an agonist with lower affinity than at CRHR1; supported by functional and binding papers.","interaction_type":"direct binding","direction_and_effect":"CRH is a full agonist at CRHR2 [DB:GtoPdb]. Human CRF2 receptor cells responded to rat/human CRF and sauvagine with increased cAMP [PMID:8536644]. Both hCRF1 and hCRF2(a) mobilised calcium in HEK293 cells but not in SK-N-MC cells [PMID:15450949]. UniProt says CRH acts on CRHR1 and to a lower extent CRHR2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond receptor-alone assays. The CRF2alpha form is the one tested; no human CRF2beta homolog evidence is reported [PMID:8536644].","affinity_potency":[{"value":"EC50 approximately 20 nM","assay":"cAMP accumulation with rat/human CRF","system":"cells transfected with human CRF2 receptor","cite":"PMID:8536644"},{"value":"pKd 6.5 to 7.400000095367432","assay":"GtoPdb curated affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"},{"value":"pKd 5.9 to 6.9","assay":"GtoPdb curated affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptors in transfected cells (HEK293, others) [PMID:8536644, PMID:15450949]. The mouse pair is inferred from human evidence.","localisation_and_range":"CRH is flagged secreted and CRHR2 a receptor [flag].","caveats":"All papers read as abstracts only. CRH is less potent than sauvagine at CRF2 (EC50 approximately 1 nM) [PMID:8536644].","key_references":[{"PMID":"8536644","why":"Human CRF2 cloning with CRF cAMP response"},{"PMID":"11123370","why":"Binding to hCRF2alpha with different radioligands"},{"PMID":"15450949","why":"Calcium signalling by hCRF2(a) depends on cell type"}],"covers":["LR000373","LR003879"]},"LR003897":{"pair":"CX3CL1 -> CX3CR1","headline":"Well-supported direct binding and agonism of CX3CR1 by the CX3CL1 chemokine domain, shown by mutagenesis, NMR and binding assays in human systems.","interaction_type":"direct binding","direction_and_effect":"CX3CL1 is an agonist of CX3CR1; it induces adhesion and migration, with migration needing pertussis toxin-sensitive G protein signalling and adhesion not [PMID:9390561]. Mutants separate binding from signalling: R48A binds but cannot induce chemotaxis, F50A shows no detectable binding [PMID:11432858]. An NMR titration with an N-terminal CX3CR1 peptide showed this receptor region contacts the chemokine domain [PMID:9931005]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The chemokine domain alone is sufficient for signalling and binds CX3CR1 [PMID:23125415]. That paper also reports that integrins alphavbeta3 and alpha4beta1 form a ternary complex with CX3CL1 and CX3CR1, and that an integrin-binding-defective mutant is an antagonist of CX3CR1 (title) [PMID:23125415]. Three CX3CR1 isoforms (standard and two N-terminally extended) bound CX3CL1 with similar steady-state affinity but different kinetics [PMID:14607932].","affinity_potency":[{"value":"pIC50 8.9","assay":"affinity value recorded by curators for the CX3CR1 isoform study; GtoPdb lists pIC50 units","system":"human CX3CR1 isoforms in HEK-293 cells","cite":"PMID:14607932"}],"species_and_systems":"Experiments are human ligand and human receptor, using recombinant proteins and transfected cells; mouse pair is projected from human evidence (ortholog inferred). Structures are listed in PDB 7XBX [DB:PDB 7XBX].","localisation_and_range":"Ligand carries both secreted and transmembrane flags [flag]; papers describe fractalkine as membrane-tethered with a chemokine domain atop a mucin stalk, acting in adhesion and migration (juxtacrine) [PMID:9390561].","caveats":"Four of the five shown papers were read as abstract only. The pIC50 value is a curator field not quoted in the abstract text. No mouse-specific experiments are reported in our evidence.","key_references":[{"PMID":"9390561","why":"Original identification of the high-affinity receptor mediating adhesion and migration"},{"PMID":"11432858","why":"Mutagenesis separating binding from signalling residues"},{"PMID":"23125415","why":"Integrin co-receptor ternary complex with CX3CR1"}],"covers":["LR000391","LR003897"]},"LR006759":{"pair":"Defb2 -> Ccr6","headline":"Mouse Defb2 binds mouse CCR6 and attracts immature dendritic cells, per one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Murine beta-defensins 2 and 3 bind murine CCR6 and chemoattract immature but not mature bone marrow-derived dendritic cells, similarly to MIP-3alpha [PMID:11714836]. Effect is chemoattraction, i.e. agonist-like; antagonism is not reported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor; bone marrow-derived dendritic cells [PMID:11714836].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only; the binding assay itself is not described in the abstract, so the assay type is unclear. The Reactome records in the dossier are human complexes (beta-defensins 1, 4A, 103 with CCR6) and do not directly cover the mouse gene [DB:Reactome]. No affinity reported.","key_references":[{"PMID":"11714836","why":"Murine beta-defensin 2/3 bind murine CCR6"}],"covers":["LR006759"]},"LR005769":{"pair":"DSG2 -> DSC2","headline":"DSG2 -> DSC2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct, PDB, UniProt), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct] [DB:PDB 5J5J] [DB:PDB 7A7D] [DB:UniProt]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR002501","LR005769"]},"LR003969":{"pair":"EFNA2 -> EPHA4","headline":"Database-only: crystal structure of the EphA4-ephrinA2 complex and a pull-down record; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"A crystal structure of the EphA4-ephrinA2 complex [DB:PDB 2WO3] and an IntAct pull-down [DB:IntAct]; UniProt lists EPHA4 as binder [DB:UniProt PMID:19836338]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair ortholog-inferred, mouse not.","localisation_and_range":"EFNA2 annotated transmembrane, EPHA4 transmembrane [flag].","caveats":"No curated paper evidence; support is database-only, though a structure is direct physical evidence.","key_references":[],"covers":["LR000478","LR003969"]},"LR003978":{"pair":"EFNA3 -> EPHA5","headline":"Ephrin-A3 binds EphA5 in ELISA and repels entorhinal neurites; support is moderate.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A3 AP binds best to EphA3, EphA5 and EphA7 [PMID:22568954]. Entorhinal neurites, which express EphA5, were repelled by ephrin-A3 but not ephrin-A5 [PMID:10516308].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"ELISA, species unspecified [PMID:22568954]; rat entorhinal neurites in a stripe assay [PMID:10516308]. The human pair is ortholog-inferred.","localisation_and_range":"Both are flagged membrane-bound [flag].","caveats":"The repulsion paper hedges with 'may interact' and did not assay physical binding separately; read as an abstract only [PMID:10516308]. The ELISA paper was a browser read with an unverifiable quote [PMID:22568954].","key_references":[{"PMID":"22568954","why":"ELISA binding ranking"},{"PMID":"10516308","why":"Ephrin-A3 repels EphA5-expressing neurites"}],"covers":["LR000487","LR003978"]},"LR003987":{"pair":"EFNA4 -> EPHA6","headline":"No verified paper; BioGRID and IntAct records only.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EFNA4-EPHA6 by affinity capture-MS [DB:BioGRID]; IntAct lists an anti-tag coimmunoprecipitation association [DB:IntAct]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; the human pair is ortholog-inferred.","localisation_and_range":"EFNA4 flagged secreted and transmembrane; EPHA6 flagged membrane-bound [flag].","caveats":"All judged papers were review-only or abstract-insufficient; support is database records only.","key_references":[],"covers":["LR000496","LR003987"]},"LR003996":{"pair":"EFNA5 -> EPHA7","headline":"Ephrin-A5 binds EphA7 in rat striatum and by ELISA; direct binding evidence.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A2, ephrin-A3 and ephrin-A5 bind EphA7 but not EphA4 in rat striatal tissue [PMID:10366629]. Ephrin-A5 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat striatal lysates [PMID:10366629]; ELISA, species unspecified [PMID:22568954]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; EPHA7 flagged secreted and transmembrane [flag].","caveats":"10366629 was an abstract-only read; 22568954 a browser read with unverifiable quote. BioGRID and IntAct records exist [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"10366629","why":"Ephrin-A5 binds EphA7 in rat striatum"},{"PMID":"22568954","why":"ELISA across EphA receptors"}],"covers":["LR000505","LR003996"]},"LR005796":{"pair":"EGFL7 -> NOTCH2","headline":"Secreted EGFL7 binds human NOTCH2 by co-IP and acts as a Notch antagonist; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Secreted EGFL7 binds a Notch region involved in ligand-mediated activation and acts as an antagonist of Notch signalling; EGFL7 expression in neural stem cells decreased Notch-specific signalling [PMID:19503073].","molecular_requirements":"Not reported in our evidence beyond Notch receptors binding EGFL7 via EGF-like domains; control receptors with EGF-like domains did not interact [PMID:19503073].","affinity_potency":[],"species_and_systems":"Endogenous human NOTCH2 co-immunoprecipitated recombinant human EGFL7 in cell lines; tagged proteins in HEK293 cells [PMID:19503073]. BioGRID lists a two-hybrid record [DB:BioGRID].","localisation_and_range":"EGFL7 is secreted [flag] and the Notch receptor is transmembrane [flag]; binding was retained with the two proteins on apposing cells [PMID:19503073].","caveats":"One paper supports all three Notch paralogs, and this row has no independent confirmation. No affinity reported in our evidence.","key_references":[{"PMID":"19503073","why":"EGFL7 binds Notch1-4 and antagonises Notch signalling"}],"covers":["LR002528","LR005796"]},"LR011988":{"pair":"ENG -> ACVR2A:ACVRL1","headline":"ENG with ACVR2A:ACVRL1 rests only on BioGRID and UniProt records; no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as Receptor-Receptor with a stimulatory modulatory effect in our records. Database records: BioGRID lists ENG-ACVR2A affinity capture-Western [DB:BioGRID]; UniProt states endoglin interacts with ACVRL1 [DB:UniProt].","molecular_requirements":"The complex is ACVR2A plus ACVRL1; the databases show ENG-ACVR2A and ENG-ACVRL1 contacts separately, not the assembled complex [DB:BioGRID][DB:UniProt].","affinity_potency":[],"species_and_systems":"Species of the experiments is not reported in our evidence; human entities.","localisation_and_range":"ENG is flagged as a receptor, ACVR2A and ACVRL1 as receptors [flag]; ligand-like role of ENG not supported by our evidence.","caveats":"No curator-verified papers (3 pending). Support is from databases only; ENG is itself a receptor/co-receptor, so this is receptor-receptor association rather than a ligand-receptor event.","key_references":[],"covers":["LR011988"]},"LR005859":{"pair":"EPHB3 -> EFNB1","headline":"Eph B3-ephrin-B1 pair supported by an IntAct co-IP and UniProt statements; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNB1 entry) states it can also bind EPHB2 and EPHB3 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct lists an anti-tag coimmunoprecipitation [DB:IntAct EBI-54525293], which does not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002591","LR005859"]},"LR005877":{"pair":"FAM3B -> FGFR2","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR2-specific evidence is thin.","interaction_type":"functional only","direction_and_effect":"The paper shows FAM3B as an FGFR ligand in Xenopus, with ERK activation via FGFR1 [PMID:33975953]. Purified human FAM3B was incubated with Fc-tagged human FGFR1-4 ectodomains, with FGFR2-Ecto-Fc one of the panels; the excerpts do not show the FGFR2 result itself [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR2 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is secreted [flag] and detected in HEK293T medium [PMID:33975953].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002610","LR005877"]},"LR005886":{"pair":"Fcer2a -> Itgb2","headline":"CD18 is the shared chain of the CD23-binding integrins CD11b-CD18 and CD11c-CD18; evidence is at complex level, one paper.","interaction_type":"direct binding","direction_and_effect":"CD23 binds cells expressing CD11b-CD18 or CD11c-CD18 and activates monocytes (agonist) [PMID:7621072].","molecular_requirements":"CD18 alone is not shown to be sufficient: CD11a-CD18 did not bind, so the alpha chain (CD11b or CD11c) determines binding [PMID:7621072]. Tools scoring this pair on ITGB2 alone should require ITGAM or ITGAX.","affinity_potency":[],"species_and_systems":"Experiments used human CD23 and human integrins (curator fields) in COS transfectants and monocytes; the mouse pair is ortholog-inferred and no mouse experiment is in our evidence.","localisation_and_range":"Fcer2a flagged secreted and receptor; itgb2 flagged not secreted [flag].","caveats":"Single paper; the pair rests on a companion row of the CD11b/CD11c result. No affinity reported.","key_references":[{"PMID":"7621072","why":"CD23 binds CD11b-CD18 and CD11c-CD18"}],"covers":["LR005886"]},"LR005895":{"pair":"FGF2 -> CSPG4","headline":"NG2/CSPG4 binds FGF2 directly via its core protein and acts as an FGF co-receptor; one primary paper.","interaction_type":"direct binding","direction_and_effect":"FGF-2 bound NG2 in a glycosaminoglycan-independent, core-protein-mediated manner, and the proteoglycan alone retained FGF-2 on the cell membrane for receptor presentation [PMID:23124902]. NG2 loss reduced FGF-driven pericyte proliferation and corneal angiogenesis in mice, and decreased FGFR phosphorylation in human smooth-muscle-like cells [PMID:23124902].","molecular_requirements":"The NG2 ectodomain suffices; the cytoplasmic domain contributes little. NG2 also associated with FGFR1 and FGFR3 independent of ligand [PMID:23124902]. Effect is co-receptor, not a stand-alone receptor.","affinity_potency":[],"species_and_systems":"Recombinant protein binding, live cells, NG2-null mouse cells and corneas, and siRNA-treated human smooth-muscle-like cells [PMID:23124902]. BioGRID lists reconstituted complex, FRET and affinity capture [DB:BioGRID].","localisation_and_range":"Both annotated secreted and transmembrane-capable [flag]; NG2 is membrane-bound, so action is on or near the cell surface.","caveats":"One paper; no affinity value. The VEGF response was unaffected, so effects are FGF specific [PMID:23124902].","key_references":[{"PMID":"23124902","why":"FGF-2 binds NG2 core protein; NG2 required for FGF responses"}],"covers":["LR002629","LR005895"]},"LR008496":{"pair":"FN1 -> ITGAV:ITGB6","headline":"Direct binding of fibronectin by alphaVbeta6 shown by affinity chromatography in two 1990s papers.","interaction_type":"direct binding","direction_and_effect":"FN1 is annotated stimulatory [flag]. AlphaVbeta6 binds fibronectin on affinity chromatography of FG-2 pancreatic carcinoma lysates [PMID:1532572]; a secreted ectodomain also binds fibronectin [PMID:8120056].","molecular_requirements":"The cytoplasmic and transmembrane domains are not needed for binding to fibronectin in the affinity chromatography assay [PMID:8120056]. The heterodimer is alphaV plus beta6.","affinity_potency":[],"species_and_systems":"Human carcinoma cell lines [PMID:1532572]; recombinant secreted form expressed in CHO cells [PMID:8120056].","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Both papers abstract-only. BioGRID FN1-ITGB6 reconstituted complex cites the same 1992 paper [DB:BioGRID]. Two review-only papers were not used.","key_references":[{"PMID":"1532572","why":"AlphaVbeta6 identified as fibronectin-binding integrin"},{"PMID":"8120056","why":"Secreted ectodomain binds fibronectin"}],"covers":["LR008496"]},"LR005949":{"pair":"GDF3 -> ACVR1C","headline":"GDF3 signals via ALK7 (ACVR1C) with Cripto in adipose tissue; mouse functional evidence, binding not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 can signal via ALK7 and Cripto [PMID:18480259]. Gdf3-/- mice had less adipose tissue and partial resistance to diet-induced obesity, phenocopied by ALK7-deficient mice [PMID:18480259]. Agonist [PMID:18480259][DB:GtoPdb].","molecular_requirements":"Cripto is the co-receptor named alongside ALK7 [PMID:18480259][DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse knockouts and signalling assays; curators label mouse ligand and receptor [PMID:18480259].","localisation_and_range":"GDF3 is flagged secreted [flag]; acts in adipose tissue [PMID:18480259].","caveats":"Abstract only. No direct binding data. The signalling readout in the abstract is not detailed.","key_references":[{"PMID":"18480259","why":"GDF3 signals via ALK7 and Cripto; matching Gdf3 and Alk7 knockout phenotypes"}],"covers":["LR002684","LR005949"]},"LR005958":{"pair":"GDNF -> SDC3","headline":"Direct binding to syndecan-3 heparan sulfate chains reported, for matrix-immobilised GDNF.","interaction_type":"direct binding","direction_and_effect":"Immobilised GDNF binds syndecan-3 heparan sulfate chains with high affinity, mediating cell spreading and neurite outgrowth via Src kinase, and promoting cortical neuron migration in a syndecan-3-dependent manner [PMID:21200028].","molecular_requirements":"Syndecan-3 may directly transduce GFL signals or act as a coreceptor presenting GFLs to RET [PMID:21200028].","affinity_potency":[{"value":"Kd between 10 and 50 nM","assay":"surface plasmon resonance, GDNF/NRTN/ARTN binding to heparin/HS","system":"heparin or heparan sulfate, not syndecan-3 protein itself","cite":"PMID:21200028"}],"species_and_systems":"Cortical neurons and mice lacking syndecan-3 or GDNF; curators record human ligand and receptor. Mouse pair is ortholog-inferred [PMID:21200028].","localisation_and_range":"Matrix-bound (immobilised) GDNF acts at cell contact; syndecan-3 is a transmembrane proteoglycan [PMID:21200028]; GDNF is flagged secreted [flag].","caveats":"Affinity is for heparin/heparan sulfate, not the core protein. Soluble GDNF uses the GFRA/RET route instead [PMID:21200028]. Abstract plus full-text excerpts of one paper; no database support.","key_references":[{"PMID":"21200028","why":"GDNF binds syndecan-3 HS chains; cortical neuron migration"}],"covers":["LR002693","LR005958"]},"LR009369":{"pair":"GNAI2 -> ADRA2A","headline":"GNAI2-ADRA2A is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a FRET record [DB:BioGRID][PMID:15782186]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR009369"]},"LR007389":{"pair":"GNRH2 -> GNRHR2","headline":"Database-asserted only: Reactome records GNRHR2 binding GNRH1,2; curated papers were abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and assay of the Reactome citations not reported in our evidence [PMID:11707068][PMID:6090951][PMID:9419371].","localisation_and_range":"GnRH II is annotated as secreted and GNRHR2 as a transmembrane receptor [flag].","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Four curated judgements were 'abstract_insufficient'. Reactome lists GNRH1 and GNRH2 together, so evidence is not specific to GNRH2.","key_references":[],"covers":["LR007389"]},"LR005967":{"pair":"GPC6 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC6 evidence is class-level.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Evidence is for 'glypican' as a class. GPC6 was detected in the LRRTM4-Fc sample but is not named in the abstract; direct cell-free binding was shown for GPC4 only [PMID:23911103].","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002702","LR005967"]},"LR005976":{"pair":"HGF -> NRP1","headline":"HGF binds neuropilin-1 in vitro and NRP1 knockdown reduces HGF signalling; two papers, direct binding, likely a co-receptor role.","interaction_type":"direct binding","direction_and_effect":"HGF binds NRP1 immobilised on an optical biosensor [PMID:15695515]. In HUVECs, NRP1 or NRP2 knockdown decreased HGF-induced c-Met phosphorylation, and NRP1 was essential for HGF-mediated angiogenesis in a mouse Matrigel model [PMID:18065694]. NRP1 therefore acts as a co-receptor that potentiates c-Met signalling, not as a stand-alone receptor [PMID:18065694].","molecular_requirements":"The N-terminal domain of HGF is involved in the NRP binding [PMID:18065694]. Binding is ionic-strength-dependent and inhibited by heparin, suggesting a heparin-mimetic site on NRP1 [PMID:15695515]. Dependence on c-Met is implied by the knockdown data [PMID:18065694].","affinity_potency":[],"species_and_systems":"Human proteins and human cells (biosensor, HUVECs); in vivo angiogenesis was tested in a mouse Matrigel model [PMID:15695515][PMID:18065694].","localisation_and_range":"NRP1 is flagged as both secreted and transmembrane [flag]; the experiments used cell-surface or immobilised NRP1.","caveats":"The biosensor binding is largely electrostatic and heparin-competable, and the same assay detected many other heparin-binding proteins, so specificity is limited [PMID:15695515]. Only one paper has full text; the other was read as an abstract [PMID:18065694].","key_references":[{"PMID":"18065694","why":"HGF binds NRP1/NRP2; knockdown reduces c-Met signalling and angiogenesis"},{"PMID":"15695515","why":"Biosensor binding of HGF/SF to Npn-1"}],"covers":["LR002711","LR005976"]},"LR005985":{"pair":"HMGB1 -> LRP1","headline":"Direct binding of HMGB1 to purified LRP1 reported in a chondrocyte ligandome study; abstract-only, no affinity value.","interaction_type":"direct binding","direction_and_effect":"HMGB1 is one of ten ligands whose direct LRP1 binding was confirmed. Affinity correlated with endocytosis rate, and LRP1 mediates endocytosis of these ligands in cartilage [PMID:36028175]. Direction is LRP1 uptake of HMGB1.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, purified LRP1 binding assays, LRP1-deficient fibroblasts and a conditional Lrp1 knockout mouse [PMID:36028175]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; LRP1 is a cell-surface endocytic receptor [PMID:36028175].","caveats":"Abstract only; HMGB1 is one of ten ligands in a large screen and no HMGB1-specific numbers are available. No database records.","key_references":[{"PMID":"36028175","why":"LRP1 ligandome in chondrocytes; direct HMGB1 binding"}],"covers":["LR002737","LR005985"]},"LR005994":{"pair":"HPX -> LRP1","headline":"LRP1/CD91 is the receptor for hemopexin-heme complexes; direct binding shown by Biacore, with Reactome support.","interaction_type":"direct binding","direction_and_effect":"Ligand-affinity purification identified LRP1/CD91 as the hemopexin-heme receptor; the complex is internalised, hemopexin is degraded in lysosomes and heme delivered, and LRP1-dependent heme-oxygenase-1 mRNA transcription follows in monocytes [PMID:15947085]. Reactome lists the LRP1:Hemopexin:heme complex [DB:Reactome].","molecular_requirements":"The hemopexin-heme complex, not hemopexin alone, gives high receptor affinity (Biacore) [PMID:15947085].","affinity_potency":[],"species_and_systems":"Human hemopexin; LRP1-expressing COS cells and monocytes [PMID:15947085]. The mouse pair is ortholog-inferred.","localisation_and_range":"HPX is flagged as secreted [flag]; plasma and cerebrospinal fluid ligand [PMID:15947085].","caveats":"Abstract-only reading; the affinity value is not given in our evidence. One further row was judged review_only.","key_references":[{"PMID":"15947085","why":"Ligand-affinity purification and Biacore: LRP1 is the hemopexin-heme receptor"}],"covers":["LR002746","LR005994"]},"LR009396":{"pair":"HSP90AA1 -> ERBB2","headline":"Database records only; no curator-verified paper supports this pair as a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists 12 records, mostly affinity-capture-western [DB:BioGRID]; IntAct lists 6 [DB:IntAct]. Species of the experiments is not reported in our evidence beyond the human entities.","localisation_and_range":"The ligand carries no secreted flag [flag]; localisation of the interaction is not reported in our evidence.","caveats":"No verified paper; one row judged different_entity and one review_only.","key_references":[],"covers":["LR009396"]},"LR008559":{"pair":"HSPG2 -> PTPRS","headline":"Weak, indirect support: the paper shows heparan sulfate proteoglycans agrin and collagen XVIII bind avian cPTPsigma, not perlecan.","interaction_type":"functional only","direction_and_effect":"HSPGs are reported as a class of ligand for cPTPsigma, with binding totally dependent on heparan sulfate chains [PMID:11865065]. Perlecan is not named in the abstract; agrin and collagen XVIII are [PMID:11865065].","molecular_requirements":"Binding needs the heparan sulfate chains and a site in the first immunoglobulin-like domain of cPTPsigma [PMID:11865065].","affinity_potency":[],"species_and_systems":"Avian cPTPsigma (the abstract's avian orthologue) with retinal basal lamina components in vitro; curators record human [PMID:11865065].","localisation_and_range":"PTPRS is flagged secreted and transmembrane [flag]; ligands are matrix-associated in the retinal basal lamina [PMID:11865065].","caveats":"The paper does not show perlecan binding; the pair rests on class-level inference. Glycan-mediated binding, not a protein epitope. Abstract only.","key_references":[{"PMID":"11865065","why":"HSPGs (agrin, collagen XVIII) bind cPTPsigma via heparan sulfate"}],"covers":["LR008559"]},"LR008577":{"pair":"ICAM2 -> ITGAL:ITGB2","headline":"ICAM-2 is an LFA-1 ligand: T-cell co-stimulation on immobilised ICAM-2 shows functional activity; direct-binding data sit on the ITGAL row.","interaction_type":"functional only","direction_and_effect":"LFA-1 co-stimulation of T cells on immobilised ICAM-1, -2 and -3 gave graded proliferation (high, intermediate, weak respectively) with distinct IL-10 and TNF-alpha profiles, agonist action [PMID:10427988].","molecular_requirements":"LFA-1 is the ITGAL:ITGB2 complex; UniProt and Reactome list the complex as the ICAM receptor [DB:UniProt][DB:Reactome].","affinity_potency":[],"species_and_systems":"Human T cells on immobilised ICAMs [PMID:10427988]; a second paper used pig ICAM-2 with human LFA-1 [PMID:15023143].","localisation_and_range":"Cell-surface adhesion molecules; contact-dependent.","caveats":"Both papers are abstract-only. PMID 15023143 concerns pig ICAM-2 and its curated sentence is about sequence conservation, not a binding result.","key_references":[{"PMID":"10427988","why":"Graded T-cell co-stimulation by ICAM-1/2/3 through LFA-1"}],"covers":["LR008577"]},"LR007299":{"pair":"IL17F -> IL17RA:IL17RC","headline":"IL-17F signals through IL-17RA:IL-17RC; a human crystal structure with IL-17RA and database records support it; chain-level evidence only.","interaction_type":"direct binding","direction_and_effect":"Agonist. GtoPdb lists IL17F with IL17RA and IL17RC [DB:GtoPdb]. UniProt says IL17RC binding of the IL17F homodimer triggers TRAF6 and NF-kappa-B signalling [DB:UniProt].","molecular_requirements":"A crystal structure shows one IL-17RA bound to one IL-17F homodimer (1:2) [PMID:19838198]. Both IL-17RA and IL-17RC can bind independently but both are necessary for signalling [PMID:19838198]. UniProt says IL17F homodimer forms predominantly complexes with IL17RC homodimer, whereas IL17A-IL17F favours IL17RA-IL17RC [DB:UniProt]. PDB 6HG4 and 6HG9 are IL-17RC with IL-17F [DB:PDB 6HG4].","affinity_potency":[],"species_and_systems":"Human purified proteins, X-ray crystallography [PMID:19838198]. Mouse sepsis study for shared IL-17RA subunit [PMID:25204502].","localisation_and_range":"Transmembrane receptor complex [flag]; IL-17F secreted [flag]. Reactome places it at the plasma membrane [DB:Reactome].","caveats":"Structure covers only the IL-17RA chain; the mouse paper does not name the partner chain and its experiments found IL-17F not required for LPS shock [PMID:25204502]. UniProt suggests IL-17F may prefer IL-17RC homodimers over the heterodimer [DB:UniProt].","key_references":[{"PMID":"19838198","why":"Crystal structure of IL-17RA with IL-17F; heterodimer formation"},{"PMID":"25204502","why":"Mouse evidence for IL-17RA as shared subunit"}],"covers":["LR007299"]},"LR008388":{"pair":"IL1RAPL1 -> PTPRS","headline":"IL1RAPL1 binds PTPRS in a human interactome screen with SPR; single paper.","interaction_type":"direct binding","direction_and_effect":"SPR validated IL1RAPL1 with PTPRS (marked as a new interaction in the paper's table) [PMID:32822567]. Effect direction is not reported in our evidence.","molecular_requirements":"Ectodomain-Fc fusions were used; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ectodomain-Fc proteins, ELISA screen with SPR validation [PMID:32822567].","localisation_and_range":"Both flagged membrane proteins [flag].","caveats":"One primary paper; the curated evidence sentence concerns IL1RAP and IL1RAPL1-PTPRD rather than this pair, but the SPR table lists IL1RAPL1/PTPRS [PMID:32822567]. No database support.","key_references":[{"PMID":"32822567","why":"Human IgSF interactome with SPR"}],"covers":["LR008388"]},"LR002799":{"pair":"IL27 -> IL6ST","headline":"gp130 (IL6ST) is the signalling chain for IL-27 per databases; the one paper instead shows free p28 antagonising gp130.","interaction_type":"conflicting","direction_and_effect":"The paper reports that the heterodimeric IL-27 signals through IL-27R\u03b1 combined with gp130, but its own finding is that IL-27p28 alone, independent of EBI3, antagonised gp130-mediated signalling and IL-6-driven IL-17 and IL-10 production (antagonist) [PMID:21057510]. GtoPdb lists IL27-IL6ST as agonist [DB:GtoPdb].","molecular_requirements":"Gp130 works with IL-27R\u03b1; UniProt states gp130 engages site 3 of IL27 [DB:UniProt P40189]. Free p28 reduced STAT1/STAT3 phosphorylation by IL-6 and IL-27 and, in SPR, inhibited IL-6-sIL-6R\u03b1 interaction with chip-bound gp130; the IL-27p28-gp130 interaction itself was modelled, and its nature remains unclear [PMID:21057510].","affinity_potency":[],"species_and_systems":"Experiments used mouse cells and mice (bone-marrow macrophages and dendritic cells, CD4+ T cells, transgenic mice) [PMID:21057510]; the curator record lists human. The human pair is ortholog-inferred. Structures 7U7N and 8D85 contain both chains [DB:PDB 7U7N].","localisation_and_range":"IL-27 is flagged secreted and gp130 transmembrane [flag].","caveats":"Direction conflicts between sources: the database says agonist, the paper reports antagonism by free p28. The heterodimer-gp130 statement in the paper is background. Full-text excerpts show no direct measurement of IL-27-gp130 binding [PMID:21057510].","key_references":[{"PMID":"21057510","why":"IL-27p28 antagonises gp130 signalling; IL-27 background via IL-27R\u03b1 plus gp130."}],"covers":["LR002799","LR006041"]},"LR007929":{"pair":"INHA:INHBA -> ACVR1C:ACVR2A","headline":"Inhibin-A (INHA:INHBA) to ACVR1C:ACVR2A: database support, mostly via activin A; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA and INHBA with ACVR2A as agonist [DB:GtoPdb]. UniProt notes activin A can form a non-signalling complex with ACVR1 and a type II receptor, rendering receptors unavailable to BMPs [DB:UniProt]. Inhibin-A effect is not directly evidenced in our evidence.","molecular_requirements":"Type II chain ACVR2A binds activin A/inhibin per databases; UniProt says it binds inhibin-A/INHA-INHBA [DB:UniProt]. PDB 7U5P shows ACVR2A ligand-binding region with activin A [DB:PDB 7U5P]. Type I chain ACVR1C is not specifically evidenced.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence. X-ray structure PDB 7U5P (35643319) [DB:PDB 7U5P]; BioGRID has INHA and INHBA with ACVR2A [DB:BioGRID 275207][DB:BioGRID 2513581].","localisation_and_range":"Ligand heterodimer flagged secreted [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. The PDB structure is activin A (INHBA) with the receptor, not the INHA:INHBA heterodimer; evidence concerns INHBA rather than the inhibin heterodimer.","key_references":[],"covers":["LR007929"]},"LR008478":{"pair":"IRAK4 -> TLR4","headline":"IRAK4 to TLR4 is recorded only from interaction databases; not an extracellular ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID records an affinity capture-western result [DB:BioGRID] and IntAct records an anti-tag co-immunoprecipitation [DB:IntAct], both for IRAK4 and TLR4-related entries.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"No secretion flag for the ligand and no interaction class in the dossier.","caveats":"No papers were judged beyond one review-only row. Co-immunoprecipitation does not show direction or signalling effect.","key_references":[],"covers":["LR008478"]},"LR008568":{"pair":"ITGB3BP -> ITGB5","headline":"ITGB3BP to ITGB5 rests on one BioGRID affinity-capture record; likely not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Only BioGRID affinity capture-western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Judged different_entity; no paper support.","key_references":[],"covers":["LR008568"]},"LR007974":{"pair":"JAG1 -> VASN","headline":"Jagged1 binds vasorin in a recombinant screen; one paper only, with limited detail.","interaction_type":"direct binding","direction_and_effect":"A SAVEXIS recombinant protein interaction screen identified vasorin as a receptor for Jagged ligands [PMID:35922511]. IntAct records SPR for the pair [DB:IntAct]. Effect direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant proteins; JAG1 and VASN mRNA were in spatially bordering cells in human lymph nodes (JAG1 in corona, VASN in germinal centre) [PMID:35922511].","localisation_and_range":"VASN is flagged as not transmembrane [flag]; JAG1 transmembrane [flag]. Lymph node data suggest cell-contact potential [PMID:35922511].","caveats":"Single screening paper; the curator noted that Results were not provided and the claim comes from the Discussion. No affinity in our evidence.","key_references":[{"PMID":"35922511","why":"Interactome screen naming JAG1-VASN"}],"covers":["LR007974"]},"LR008289":{"pair":"JAML -> CD320","headline":"Only a single IntAct solid-phase assay record supports JAML-CD320; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the IntAct record is a solid phase assay [DB:IntAct].","localisation_and_range":"Both partners are flagged transmembrane [flag]; no paper addresses range.","caveats":"The only support is one IntAct record (solid phase assay) [DB:IntAct]; the single judged paper was abstract-insufficient. Treat as unverified.","key_references":[],"covers":["LR008289"]},"LR011100":{"pair":"KRTAP4-12 -> DLK2","headline":"Only a yeast two-hybrid IntAct record; no evidence that this is a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a two-hybrid physical association from a large-scale screen; species and system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged paper was review_only, so no curator-verified evidence exists. A two-hybrid hit does not show a ligand-receptor relationship, and KRTAP4-12 is a keratin-associated protein, so this is likely a screening artefact.","key_references":[],"covers":["LR011100"]},"LR000999":{"pair":"LAMB1 -> ITGA3","headline":"Laminin-10/11 (beta1-containing) is an integrin alpha3beta1 ligand by binding and adhesion blockade; abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 is a high-affinity ligand for integrin alpha3beta1, and CD151 potentiates the binding [PMID:15677332]. Anti-alpha3 or anti-beta1 antibodies blocked adhesion of A549 cells to laminin-10/11 [PMID:9624186]. Annotated stimulatory.","molecular_requirements":"Needs integrin alpha3 with beta1; CD151 sustains activation [PMID:15677332]. Laminin-10 (alpha5beta1gamma1) is a heterotrimer and LAMB1 was not tested alone.","affinity_potency":[],"species_and_systems":"Human A549 cells for adhesion [PMID:9624186]; system for the binding paper not reported in our evidence. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA3 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers were abstract reads; LAMB1 is inferred from laminin-10/11 composition. Two further papers were review_only. No Kd is given in this dossier for this pair.","key_references":[{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand"},{"PMID":"9624186","why":"Antibody-blocked adhesion to laminin-10/11"}],"covers":["LR000999","LR004418"]},"LR001002":{"pair":"LAMB1 -> ITGB1","headline":"Laminin beta1-containing laminins engage integrin beta1 pairings (alpha3, alpha6, alpha7); many binding and blocking studies, chain-level only.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha3beta1 [PMID:16413178]; laminin-10/11 is a high-affinity alpha3beta1 ligand [PMID:15677332]. Anti-beta1 antibodies blocked platelet adhesion to laminin [PMID:10585296] and A549 adhesion to laminin-10/11 [PMID:9624186]; alpha7beta1 mediates myoblast migration on laminin-1/-2 [PMID:11278916]. Annotated stimulatory.","molecular_requirements":"ITGB1 works in alpha/beta heterodimers with specificity set by the alpha partner; ITGB1 alone and LAMB1 alone were not tested. A PDB entry has chains P07942 and P05556 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha3beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins, human A549 cells and platelets, and human-labelled myoblasts [PMID:16413178][PMID:9624186][PMID:10585296][PMID:11278916]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"The Kd belongs to alpha3beta1. Most confirming papers are abstract-only, antibody-blocking adhesion readouts. One further paper was review_only.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"},{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand"},{"PMID":"11278916","why":"Alpha7beta1 and myoblast migration on laminin"}],"covers":["LR001002","LR004421"]},"LR001011":{"pair":"LAMC1 -> ITGA7","headline":"LAMC1 (in laminin-211/221 and laminin-1/2) binds integrin alpha7 with Kd 0.64 nM; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221 bound recombinant alpha7X1beta1 in solid-phase assays [PMID:16413178]. Alpha7beta1 is described as a receptor for laminin-1 and -2 mediating myoblast migration on laminin [PMID:11278916]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Binder is the alpha7beta1 heterodimer and ligand the assembled heterotrimer; single chains were not tested [PMID:16413178]. For PMID:11278916 the curator notes the assay cannot separate the chains of laminin-1 and -2.","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha7X1beta1 vs laminin-211/221","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; transfected HEK293 cells in PMID:11278916 (abstract only). Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. The second paper was read as abstract only and is largely about alpha7 cytoplasmic-domain signalling.","key_references":[{"PMID":"16413178","why":"Kd for alpha7X1beta1 vs laminin-211/221"},{"PMID":"11278916","why":"alpha7beta1 as laminin-1/-2 receptor in myoblast motility, abstract only"}],"covers":["LR001011","LR004429"]},"LR001020":{"pair":"LEFTY2 -> ACVR2B","headline":"Lefty2 antagonism via ActRIIB rests on a mouse genetic interaction and a rescue experiment, read from an abstract only.","interaction_type":"functional only","direction_and_effect":"Antagonist of Nodal signalling; Lefty inhibition was rescued by excess ActRIIA or ActRIIB, and a genetic interaction between lefty2 and ActRIIB was shown in mouse [PMID:11952836].","molecular_requirements":"ActRIIA or ActRIIB can act as the type II receptor, with ALK4 as type I and Cripto as membrane-bound co-receptor for Nodal [PMID:11952836].","affinity_potency":[],"species_and_systems":"Frog animal caps, mouse genetics, chick embryos. The human pair is ortholog-inferred [PMID:11952836].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]. Lefty diffused faster than Nodal in chick embryos [PMID:11952836].","caveats":"No direct binding is shown; competitive binding is the authors' suggestion. Abstract-only read; no database records. The pair record carries a Stimulatory modulatory effect, which conflicts with the antagonist direction in the paper.","key_references":[{"PMID":"11952836","why":"Genetic interaction lefty2/ActRIIB in mouse; competitive-binding model"}],"covers":["LR001020","LR004438"]},"LR002889":{"pair":"LGALS3 -> PECAM1","headline":"PECAM1 (CD31) was co-purified from endothelial cells on galectin-3 affinity columns; binding is shown only by pull-down, with no functional confirmation.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 affinity purification extracted PECAM-1 among four endothelial membrane glycoproteins; effect direction is not established for PECAM1 [PMID:28364041].","molecular_requirements":"Not reported in our evidence for PECAM1. The major galectin-3 ligand in this paper was CD146, which was the one functionally validated by siRNA [PMID:28364041].","affinity_potency":[],"species_and_systems":"Human vascular endothelial cells; mouse pair is ortholog-inferred [PMID:28364041].","localisation_and_range":"PECAM1 carries a transmembrane flag [flag]; galectin-3 has a secreted flag [flag].","caveats":"Abstract only. PECAM1 is one of four co-purified glycoproteins; its functional role in galectin-3-induced cytokine secretion was not tested, and CD146 was the major ligand. Affinity purification may reflect glycan-mediated binding to a abundant glycoprotein rather than a dedicated receptor interaction.","key_references":[{"PMID":"28364041","why":"Galectin-3 affinity purification identifies PECAM-1 among endothelial binders"}],"covers":["LR002889","LR006123"]},"LR002898":{"pair":"LGALS8 -> ITGA3","headline":"Galectin-8 binds alpha3beta1 integrin from carcinoma and other cells and blocks cell adhesion, inducing apoptosis; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Galectin-8 inhibited adhesion of human 1299 carcinoma cells to plates coated with integrin ligands and induced apoptosis (antagonist of adhesion); effects were not mimicked by galectin-1 or galectin-3, and Mn2+ abolished the inhibition [PMID:10852818].","molecular_requirements":"The integrin identified is alpha3beta1, so both ITGA3 and ITGB1 chains are involved; whether one chain suffices is not reported in our evidence [PMID:10852818].","affinity_potency":[],"species_and_systems":"Human 1299 carcinoma cells; alpha3beta1 also from HeLa and human endothelial cells; mouse pair is ortholog-inferred [PMID:10852818].","localisation_and_range":"Galectin-8 is a secreted protein (secreted flag [flag]); endogenous galectin-8 secreted from 1299 cells forms complexes with surface alpha3beta1 integrin [PMID:10852818].","caveats":"Abstract only. Binding is sugar-dependent (a beta-galactoside lectin reading glycans) [PMID:10852818]. BioGRID lists Affinity Capture-Western and Reconstituted Complex records [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"10852818","why":"Galectin-8 binding to alpha3beta1 integrin inhibits adhesion and induces apoptosis"}],"covers":["LR002898","LR006128"]},"LR001899":{"pair":"LY9 -> LY9","headline":"CD229 (LY9) binds itself homophilically; one paper with mutagenesis, human and mouse.","interaction_type":"direct binding","direction_and_effect":"CD229-Ig bound CD229-transfected cells but not cells expressing other CD150 family receptors; both human and mouse CD229 interacted with itself [PMID:15905546]. Curator labels agonist. CD229 relocalized to the T-B cell contact area during immune synapse formation [PMID:15905546].","molecular_requirements":"The N-terminal Ig domain mediates homophilic adhesion; E27A, E29A and R89A impaired binding and R44A enhanced it [PMID:15905546].","affinity_potency":[],"species_and_systems":"Soluble human CD229-Ig on transfected cells; human and mouse both tested; T-B cell conjugates [PMID:15905546]. IntAct lists a solid phase assay [DB:IntAct].","localisation_and_range":"Cell-surface, contact-dependent homophilic adhesion at the immune synapse [PMID:15905546]. The annotation flags it as secreted [flag], which the paper does not support.","caveats":"Abstract only. No affinity. Homophilic pairs mean one gene serves as both ligand and receptor, so CCC tools need that cell-pair context.","key_references":[{"PMID":"15905546","why":"CD229 homophilic binding mapped to N-terminal domain"}],"covers":["LR001899","LR005241"]},"LR007983":{"pair":"MPZL1 -> MPZL1","headline":"Homophilic pair resting only on one IntAct SPR record; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists surface plasmon resonance for the self-pair [DB:IntAct O95297-O95297].","localisation_and_range":"Annotated transmembrane, not secreted [flag]; adhesion-type interaction.","caveats":"No curator-confirmed paper; abstract_insufficient reads and different_entity rows only. Support is a single database record.","key_references":[],"covers":["LR007983"]},"LR002979":{"pair":"NCAN -> CNTN2","headline":"Neurocan binds TAG-1/axonin-1 (CNTN2) with high affinity in a binding assay; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Neurocan and phosphacan are high-affinity ligands of TAG-1/axonin-1; chondroitinase treatment did not affect neurocan binding [PMID:8663515].","molecular_requirements":"The chondroitin sulfate chains are not required for neurocan binding, unlike phosphacan (decreased by approximately 70%) [PMID:8663515].","affinity_potency":[{"value":"Kd 0.3 nM","assay":"binding assay","system":"neurocan with TAG-1/axonin-1","cite":"PMID:8663515"}],"species_and_systems":"Species not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Neurocan is flagged secreted [flag], so an extracellular matrix ligand for a cell-surface contactin.","caveats":"Abstract only. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","key_references":[{"PMID":"8663515","why":"Neurocan binds TAG-1/axonin-1, Kd 0.3 nM"}],"covers":["LR002979","LR006204"]},"LR002988":{"pair":"NFASC -> NRCAM","headline":"Direct neurofascin-NrCAM binding shown in transfected cells and immunoprecipitation; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Binding studies in transfected COS7 cells and immunoprecipitations reveal a direct interaction between neurofascin and NrCAM, mapped to the Ig domains of neurofascin [PMID:8922386]. Immobilised neurofascin-Fc stimulated tectal neurite outgrowth through NrCAM on the axon, but soluble neurofascin did not [PMID:8922386].","molecular_requirements":"Binding can be modulated by alternative splicing of specific stretches within neurofascin [PMID:8922386]. Subunit requirements beyond this are not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 cells and tectal cells; the species is not reported in our evidence. Paper read as abstract, with some full-text figure legends [PMID:8922386]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both are membrane glycoproteins acting heterophilically at the axon surface [PMID:8922386]. NRCAM carries a secreted flag as well as a transmembrane flag [flag].","caveats":"One paper, 1996; effect on the receptor side is shown as neurite outgrowth only when neurofascin is immobilised. Reactome records the NFASC:NRCAM complex [DB:Reactome].","key_references":[{"PMID":"8922386","why":"Direct NFASC-NRCAM interaction mapped to neurofascin Ig domains"}],"covers":["LR002988","LR006213"]},"LR001101":{"pair":"NID2 -> COL13A1","headline":"Single abstract-level report of nidogen-2 binding the type XIII collagen ectodomain by SPR, in nanomolar range; no signalling shown.","interaction_type":"direct binding","direction_and_effect":"Recombinant COL13A1 ectodomain interacted with immobilised nidogen-2 by surface plasmon resonance; nidogen-2 binding resided in pepsin-sensitive portions of the ectodomain [PMID:11956183]. No signalling or effect on a cell is shown; the curator notes the roles are inverted, with collagen XIII the transmembrane partner.","molecular_requirements":"The shed ectodomain forms 240-kDa trimers [PMID:11956183]; binding of the intact membrane protein is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant ectodomain from insect cells (curator species: human); mouse pair is ortholog-projected, not tested [PMID:11956183].","localisation_and_range":"Nidogen-2 is flagged secreted and COL13A1 transmembrane [flag]; this reads as a matrix-to-cell-surface adhesion contact rather than a diffusible signal.","caveats":"Abstract only; affinity is reported only as 'nanomolar range', with no value. Binding was shown with the shed ectodomain, not a full-length receptor. Adhesion rather than receptor signalling.","key_references":[{"PMID":"11956183","why":"SPR binding of COL13A1 ectodomain to nidogen-2"}],"covers":["LR001101","LR004512"]},"LR001110":{"pair":"NLGN3 -> NRXN3","headline":"One paper, read in full in a browser, reports all neuroligins bound all three neurexins in rat brain.","interaction_type":"direct binding","direction_and_effect":"All neuroligins bound preferentially to beta-neurexins lacking an insert, and all bound all three neurexins, by affinity chromatography of rat brain proteins on immobilised beta-neurexin-IgG [PMID:8576240].","molecular_requirements":"Preference for beta-neurexins lacking a splice insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat brain proteins (curator-listed) [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"The full-text quote is a browser read marked unverifiable with spot-check pending; the abstract itself speaks of beta-neurexins. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to all three neurexins"}],"covers":["LR001110","LR004521"]},"LR002997":{"pair":"NPPC -> NPR1","headline":"CNP-NPR1 is supported only by a BioGRID record; all eight judged papers were abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified direction or effect is available. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"CNP annotated secreted and NPR1 transmembrane [flag].","caveats":"No confirmed paper. Treat as unverified or likely weak; low confidence for CCC scoring.","key_references":[],"covers":["LR002997","LR006221"]},"LR003000":{"pair":"NPTX2 -> NPTXR","headline":"NPTXR is enriched on NP2 affinity columns; one abstract-level paper, no databases.","interaction_type":"direct binding","direction_and_effect":"NPR (NPTXR) was enriched by affinity chromatography on columns of NP2, NP1 and a toxin [PMID:9261167]. Direction or effect not reported in our evidence.","molecular_requirements":"NPTXR has a putative N-terminal transmembrane domain and is glycosylated; NPR shares 48% identity with NP2 [PMID:9261167].","affinity_potency":[],"species_and_systems":"Affinity chromatography; species not stated in dossier [PMID:9261167]. Human pair is not ortholog-inferred; mouse is.","localisation_and_range":"NPTXR is a putative integral membrane pentraxin [PMID:9261167]; NPTX2 annotated secreted [flag].","caveats":"Single abstract-only paper; association rather than measured affinity. Two further papers were abstract-insufficient.","key_references":[{"PMID":"9261167","why":"Identification of NPR as NP2-binding protein"}],"covers":["LR003000","LR006224"]},"LR008595":{"pair":"NRG1 -> ERBB2:ERBB3","headline":"NRG1 binds the ERBB2:ERBB3 complex mainly through ERBB3, with ERBB2 raising affinity and driving signalling; six abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Heregulin binds ErbB3; ErbB2 co-expression enhances binding and signalling. Little or no phosphorylation occurs with erbB3 alone, but erbB3 plus erbB2 reconstitutes a higher-affinity, signalling receptor [PMID:7514177]; both NDF isoforms signalled through ErbB-3/ErbB-2 heterodimers [PMID:8702572].","molecular_requirements":"ERBB3 is the binding chain: NDF-beta2 binds sHer3 with Kd 26 nM and about 1000-fold weaker to sHer2 [PMID:7592681]; the heregulin EGF-like domain binds HER3 domains I and II [PMID:11555649]. ErbB2 enhances binding to ErbB3 or ErbB4 [PMID:10214951]; ERBB3 itself is catalytically impaired and needs ErbB-1 or ErbB-2 [PMID:8702572].","affinity_potency":[{"value":"Kd 26 nM","assay":"native gels, light scattering and sedimentation equilibrium","system":"purified soluble ectodomains (sHer3), NDF-beta2","cite":"PMID:7592681"}],"species_and_systems":"Human ligand and receptors; phage display with receptor-IgG fusions, soluble ectodomains, transfected IL-3-dependent cells [PMID:9565587][PMID:7592681][PMID:8702572]. Human pair only.","localisation_and_range":"NRG1 is flagged secreted and transmembrane, both receptors transmembrane [flag]; PDB complexes exist (7MN5 and others) [DB:PDB 7MN5].","caveats":"All papers are abstract only. In the soluble-ectodomain study, NDF is a high-affinity ligand for Her3 but not Her2, and adding sHer2 did not raise affinity [PMID:7592681]. So the complex score depends on both chains, but direct ligand binding is shown for ERBB3 chiefly. Alpha and beta isoforms differ in their ErbB-1 partnering [PMID:8702572].","key_references":[{"PMID":"7514177","why":"ErbB2 plus ErbB3 reconstitutes the high-affinity heregulin receptor"},{"PMID":"7592681","why":"Kd 26 nM at Her3, weak at Her2"},{"PMID":"8702572","why":"Both NDF isoforms signal via ErbB-3/ErbB-2"}],"covers":["LR008595"]},"LR008487":{"pair":"NRXN3 -> NLGN2","headline":"Rests on database records only; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID]; UniProt says NLGN2 interacts with neurexins NRXN1, NRXN2 and NRXN3 (by similarity) [DB:UniProt].","localisation_and_range":"Both flagged transmembrane, non-secreted [flag].","caveats":"Judged rows were different_entity or abstract_insufficient, none confirmed; the UniProt statement is by similarity.","key_references":[],"covers":["LR008487"]},"LR004599":{"pair":"OXT -> AVPR1A","headline":"Oxytocin binds and activates AVPR1A with lower affinity than vasopressin; partial agonist at human receptor, with species differences.","interaction_type":"direct binding","direction_and_effect":"OXT activates Ca2+ signalling at human AVPR1A but as a partial agonist, about 45% of the maximal AVP response; at marmoset AVPR1A it exceeded AVP [PMID:31664130]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"Ki 34.9 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"15.8 nM (Leu8-OXT), 8.7 nM (Pro8-OXT)","assay":"125I-OVTA competition binding, versus 0.6 nM for AVP","system":"human AVPR1a in CHO cells","cite":"PMID:31664130"},{"value":"69.3 nM (Leu8-OXT), 36.2 nM (Pro8-OXT)","assay":"Ca2+ response potency, versus AVP 1.6 nM","system":"human AVPR1a","cite":"PMID:31664130"}],"species_and_systems":"Human receptor in recombinant cells; marmoset and macaque receptors also tested [PMID:31664130]. Mouse pair is ortholog-inferred.","localisation_and_range":"OXT is flagged secreted and AVPR1A a transmembrane receptor [flag].","caveats":"OXT is a lower-affinity cross-reactive ligand; the authors suggest it may partly antagonise human AVPR1a signalling [PMID:31664130]. Both key papers were read as abstract or in part; PDB structures are not listed for this pair. GtoPdb gives pKi 6.9 to 8.3 [DB:GtoPdb]. Marmoset OXT affinity is about 10-fold lower than human [PMID:31664130].","key_references":[{"PMID":"31664130","why":"affinity and efficacy of OXT versus AVP at primate AVPR1a"},{"PMID":"10519430","why":"Ki of oxytocin at V1a"}],"covers":["LR001190","LR004599"]},"LR001200":{"pair":"PDGFD -> PDGFRB","headline":"PDGFD, once proteolytically activated, is an agonistic ligand specific for PDGFRB.","interaction_type":"direct binding","direction_and_effect":"Upon limited proteolysis, PDGF-DD is activated and becomes a specific agonistic ligand for PDGFR-beta; it is described as the first known PDGFR-beta-specific ligand [PMID:11331881]. UniProt: PDGFD interacts with PDGFRB homodimers and PDGFRA:PDGFRB heterodimers [DB:UniProt].","molecular_requirements":"Active ligand is the disulphide-linked PDGF-DD homodimer after proteolytic activation [PMID:11331881].","affinity_potency":[],"species_and_systems":"Abstract only; species and system details not reported in our evidence [PMID:11331881]. UniProt records exist for both partners [DB:UniProt]. The project record lists human and mouse interactions, mouse not ortholog-inferred.","localisation_and_range":"PDGFD flagged secreted; PDGFRB transmembrane [flag]; secreted dimer after proteolysis [PMID:11331881].","caveats":"One paper, abstract only; the evidence sentence is functional-agonist wording and no numbers are reported.","key_references":[{"PMID":"11331881","why":"Identifies activated PDGF-DD as a PDGFR-beta-specific agonist"}],"covers":["LR001200","LR004609"]},"LR009738":{"pair":"PLXNB2 -> SEMA4G","headline":"No verified evidence; only a UniProt statement and one pending paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states PLXNB2 is a cell surface receptor for SEMA4C, SEMA4D and SEMA4G, by similarity [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both flagged membrane-associated [flag].","caveats":"Support rests on a by-similarity UniProt annotation; one paper is pending and unjudged. Row is classed Receptor-Receptor; orientation looks reversed.","key_references":[],"covers":["LR009738"]},"LR008298":{"pair":"PSG7 -> DCC","headline":"SPR in a large human cell-surface interactome screen showed PSG7 binding DCC; single paper, binding only.","interaction_type":"direct binding","direction_and_effect":"The paper reports SPR binding of DCC to PSG7; no effect or signalling is reported [PMID:32822567].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human ectodomain proteins, SPR with 2-fold analyte dilutions of 16-2,048 nM; no cell system [PMID:32822567].","localisation_and_range":"Receptor flagged transmembrane [flag]; PSGs are described as secreted proteins in placenta context, DCC is expressed in human placenta [PMID:32822567].","caveats":"Binding of recombinant proteins only, no functional readout, no affinity value in our evidence; in vivo relevance unknown. A single screen paper. Receptor DCC is in a different family than classical PSG partners; novel PPI.","key_references":[{"PMID":"32822567","why":"Interactome screen with SPR validation of PSG-DCC/DSCAM binding."}],"covers":["LR008298"]},"LR006399":{"pair":"RAE1 -> KLRK1","headline":"RAE-1 proteins bind NKG2D (KLRK1) in the original mouse study; a BioGRID record supports the pair.","interaction_type":"direct binding","direction_and_effect":"RAE-1 alpha, beta, gamma and delta and H60 were stained by mNKG2D-Ig fusion protein, and RAE-1 and H60 rendered cells susceptible to NK cytotoxicity [PMID:10894171]. Activating receptor, ligand on target cell.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse NKG2D-Ig and mouse cell lines (Ba/F3 transductants, F9, LL/2) [PMID:10894171]. BioGRID lists a reconstituted complex [DB:BioGRID]. The human pair is projected from mouse (ortholog inferred).","localisation_and_range":"RAE-1 is described as GPI-anchored membrane protein [PMID:10894171]; ligand is flagged not secreted [flag]. Contact-dependent.","caveats":"The dossier marks the experiment species as human, but the paper used mouse NKG2D and mouse RAE-1. No affinity reported. Pair is projected to human.","key_references":[{"PMID":"10894171","why":"RAE-1 family identified as mNKG2D ligands"}],"covers":["LR003179","LR006399"]},"LR004689":{"pair":"RELN -> ITGA3","headline":"Reelin associates with alpha3beta1 integrin in one primary paper; support is chain-level (ITGA3 alone) and single-source.","interaction_type":"direct binding","direction_and_effect":"Recombinant and native Reelin co-immunoprecipitated with alpha3 and beta1 integrin beads, and Reelin inhibited cortical neuron migration in a manner dependent on alpha3beta1 [PMID:10939329]. The curated effect is stimulatory by annotation [flag], whereas the paper reports inhibition of migration.","molecular_requirements":"The evidence is for the alpha3beta1 heterodimer; this ITGA3-alone row does not show that alpha3 suffices [PMID:10939329]. Alpha3beta1 is described as acting with VLDLR and ApoER2 in a complex [PMID:10939329].","affinity_potency":[],"species_and_systems":"Experiments used mouse and rat embryonic cortex, cultured cortical neurons and recombinant Reelin from 293T cells [PMID:10939329]. The human pair is ortholog-inferred; the mouse pair is direct.","localisation_and_range":"RELN is flagged secreted [flag]. Reelin-coated microspheres acted locally in tissue [PMID:10939329].","caveats":"Single paper only; the curator record was an abstract read, though full-text excerpts were available. Chain-only (ITGA3) attribution of a heterodimer result.","key_references":[{"PMID":"10939329","why":"Reelin binds alpha3beta1 integrin; integrin-null neurons ignore Reelin"}],"covers":["LR001290","LR004689"]},"LR004698":{"pair":"RLN3 -> RXFP1","headline":"Relaxin-3 activates RXFP1 (LGR7) in vitro and in vivo, supported by two abstract-read papers and database records.","interaction_type":"direct binding","direction_and_effect":"Synthetic human relaxin-3 showed high activity at LGR7 from various species and activated native LGR7 in rat ventricular fibroblasts, increasing MMP-2 expression, and after intraventricular infusion in rats stimulated water drinking [PMID:16411781]. It activated LGR7 via cAMP in chimeric-receptor assays as a full agonist [PMID:12506116]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Activation involves binding to both the ectodomain and exoloop 2 of LGR7 [PMID:12506116]. Other subunit requirements are not reported in our evidence.","affinity_potency":[{"value":"pKi 7.5 to 8.0","assay":"GtoPdb affinity range (pKi)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Curated as human ligand and receptor; experiments also used rat cells and rat in vivo [PMID:16411781]. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag]; paracrine or endocrine signalling to a membrane receptor.","caveats":"Both papers read as abstracts only. Relaxin-3's highest activity was at its own receptor GPCR135, so RXFP1 is a secondary target [PMID:16411781]. BioGRID lists a protein-peptide record [DB:BioGRID]. Two papers are still pending.","key_references":[{"PMID":"16411781","why":"Relaxin-3 activates native LGR7 in rat fibroblasts and in vivo"},{"PMID":"12506116","why":"H3 relaxin activates LGR7; ectodomain plus exoloop 2"}],"covers":["LR001300","LR004698"]},"LR007398":{"pair":"SEMA3A -> NRP1:PLXNA3","headline":"Only Sema3A-Nrp1 is supported, in mouse; PlexinA3 involvement is not shown here.","interaction_type":"functional only","direction_and_effect":"Sema3A interacts with Nrp1 in leptin receptor-expressing mouse MSCs, aiding osteogenesis and inhibiting adipogenesis in aging male mice [PMID:41022817].","molecular_requirements":"PlexinA3 is not mentioned in the confirmed evidence, so the three-chain requirement is not supported [PMID:41022817].","affinity_potency":[],"species_and_systems":"Aging male mice with Sema3a and Nrp1 knockouts; abstract only [PMID:41022817].","localisation_and_range":"Sema3A is flagged secreted [flag]; sensory nerves release it [PMID:41022817].","caveats":"Support is Sema3A-Nrp1 only; PLXNA3 is untested here. Abstract only; two other papers were abstract_insufficient and three review-only. Database records concern Nrp-1 bound to PlexinA generally [DB:Reactome R-HSA-399933].","key_references":[{"PMID":"41022817","why":"Sema3A-Nrp1 pathway in mouse MSCs during PEMF osteogenesis"}],"covers":["LR007398"]},"LR006489":{"pair":"SEMA3G -> PLXNA1","headline":"Weak evidence: one abstract-only paper on a SEMA3G mutation altering PlexinA receptor binding in GnRH neurons.","interaction_type":"functional only","direction_and_effect":"A SEMA3G variant from siblings with GnRH deficiency changed binding to PlexinA receptors in silico and in vitro and attenuated effects on GnRH neuron migration [PMID:32365351].","molecular_requirements":"Not reported in our evidence; the abstract-level text names PlexinA receptors generally, including PLXNA1 per the curator [PMID:32365351].","affinity_potency":[],"species_and_systems":"Human variant study with in silico, in vitro and in vivo models; the mouse pair is ortholog-inferred [PMID:32365351].","localisation_and_range":"SEMA3G is flagged secreted [flag].","caveats":"Abstract only; wild-type SEMA3G-PLXNA1 binding is not directly shown, and PLXNA1 is not named in the abstract text we have.","key_references":[{"PMID":"32365351","why":"SEMA3G mutation alters PlexinA receptor selectivity in GnRH deficiency"}],"covers":["LR003273","LR006489"]},"LR006777":{"pair":"Sema4a -> Timd2","headline":"Sema4A-Tim-2 is a mouse receptor assignment from expression cloning in one 2002 paper (abstract only).","interaction_type":"direct binding","direction_and_effect":"Expression cloning identified Tim-2 as the Sema4A receptor; Sema4A enhances T-cell activation and anti-Sema4A antibodies block experimental autoimmune encephalomyelitis in mice; curators label it agonist [PMID:12374982].","molecular_requirements":"Tim-2 named alone; no co-receptor reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor, T cells and in vivo mouse EAE [PMID:12374982]. Curator notes say Tim-2 is mouse-specific with no clear human orthologue; this is a curator note, not a dossier assay.","localisation_and_range":"Sema4a flagged secreted [flag]; paper text does not state range.","caveats":"Single paper, abstract only. No quantitative binding data. No database support.","key_references":[{"PMID":"12374982","why":"Expression cloning of Tim-2 as the Sema4A receptor"}],"covers":["LR006777"]},"LR009567":{"pair":"SEMA4D -> MET","headline":"MET is a required co-receptor for Sema4D-PlexinB1 signalling, not a direct binder; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Sema4D binding to Plexin B1 stimulates Met tyrosine kinase activity, phosphorylating both receptors; Sema4D triggers epithelial invasive growth [PMID:12198496]. Curators label modulatory effect as stimulatory.","molecular_requirements":"PlexinB1 and Met associate in a complex; Met-null cells do not respond to Sema4D unless Met is restored, so Met is required [PMID:12198496]. Sema4D binds PlexinB1, not MET directly (curator note).","affinity_potency":[],"species_and_systems":"Epithelial cells, human labels [PMID:12198496]; Reactome records the complex SEMA4D:MET:p-Y-PLXNB1 [DB:Reactome].","localisation_and_range":"Sema4D flagged secreted and transmembrane [flag].","caveats":"This is not a direct SEMA4D-MET binding pair; the evidence supports MET as a co-receptor of PLXNB1. Abstract only.","key_references":[{"PMID":"12198496","why":"Sema4D-PlexinB1 coupling with Met"}],"covers":["LR009567"]},"LR006498":{"pair":"SEMA6B -> PLXNA4","headline":"Supported only by a single abstract-only sentence that plexin-A4 bound Sema6B; no Sema6B-specific data are shown.","interaction_type":"direct binding","direction_and_effect":"Plexin-A4 bound the class 6 semaphorins Sema6A and Sema6B and mediated their axon-repulsive activities independently of neuropilin-1 [PMID:15814794].","molecular_requirements":"Neuropilin-1 is not required [PMID:15814794].","affinity_potency":[],"species_and_systems":"Plexin-A4 null mice and neurons; curator species fields say human, but the abstract describes mutant mice. Mouse pair is not ortholog-inferred in the dossier.","localisation_and_range":"Not reported in our evidence.","caveats":"One paper read as abstract only; the Sema6B result is a single clause, the abstract is truncated, and the study focuses on Sema3A. Other judged rows were abstract_insufficient or pending.","key_references":[{"PMID":"15814794","why":"States plexin-A4 bound Sema6A and Sema6B"}],"covers":["LR003282","LR006498"]},"LR004779":{"pair":"SFTPD -> TLR4","headline":"SP-D binds the soluble TLR4 extracellular domain via its CRD; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Natural and recombinant SP-D showed specific binding to soluble TLR4 extracellular domain [PMID:16834340]; functional effect is not reported in our evidence.","molecular_requirements":"Binding is Ca2+-dependent, includes deglycosylated receptor, and is blocked by a CRD-epitope antibody [PMID:16834340]. Reactome lists TLR4:LY96 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Recombinant soluble human TLR4 with human SP-D; mouse pair is ortholog-inferred [PMID:16834340].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"16834340","why":"SP-D binds sTLR2 and sTLR4 through the CRD"}],"covers":["LR001384","LR004779"]},"LR004788":{"pair":"SLIT1 -> ROBO1","headline":"Well-established SLIT1-ROBO1 guidance pair: direct binding of mouse SLIT1, functional and in vivo papers, and database records.","interaction_type":"direct binding","direction_and_effect":"Mouse SLIT1 binds ROBO1 [PMID:10433822]. Endogenous Robos mediate Slit growth-promoting effects on neurite length in Robo1;Robo2 deficient neurons [PMID:21600986]. In the presence of Slit1, both Robo1 and FLRT3 are needed to induce Netrin-1 attraction through PKA-dependent surface DCC upregulation [PMID:24560577].","molecular_requirements":"FLRT3 acts as a Robo1 coreceptor for the Netrin-1 response [PMID:24560577]. Robo1 and Robo2 act together in PMID:21600986, so single-receptor contribution is not separated there.","affinity_potency":[],"species_and_systems":"Mouse SLIT1 protein [PMID:10433822]; mouse cortical neurons [PMID:21600986]; thalamic axons [PMID:24560577], species recorded as human in the dossier but not stated in the abstract.","localisation_and_range":"SLIT1 is flagged secreted and ROBO1 transmembrane [flag]; Reactome and UniProt records agree [DB:Reactome] [DB:UniProt].","caveats":"All three papers were abstract-only. The assay format in PMID:10433822 is not named, and PMID:24560577 centres on FLRT3, with Slit1-Robo1 as background. One further row was abstract-insufficient and one pending. No affinity.","key_references":[{"PMID":"10433822","why":"Mouse SLIT1 binds ROBO1"},{"PMID":"21600986","why":"Robo-dependent Slit growth effects in neurons"},{"PMID":"24560577","why":"FLRT3 as Robo1 coreceptor with Slit1"}],"covers":["LR001393","LR004788"]},"LR001989":{"pair":"SLITRK1 -> PTPRS","headline":"SLITRK1-PTPsigma is supported by cell aggregation and knockdown/rescue synapse assays.","interaction_type":"functional only","direction_and_effect":"Slitrk1-expressing cells aggregated with PTPsigma-expressing cells [PMID:23345436]. The intracellular D2 domain of PTPsigma is required for heterologous synapse formation induced by Slitrk1 [PMID:29934346].","molecular_requirements":"PTPsigma intracellular D2 domain is required for Slitrk1-induced synapse formation [PMID:29934346]; extracellular interactions of PTPsigma with Slitrks matter for excitatory synapses [PMID:29934346].","affinity_potency":[],"species_and_systems":"Mouse L cells [PMID:23345436]; cultured rat hippocampal neurons [PMID:29934346]. Mouse pair ortholog-inferred.","localisation_and_range":"Both transmembrane (trans-synaptic contact) [flag][PMID:23345436].","caveats":"Direct binding is not shown in these papers; BioGRID lists a reconstituted complex [DB:BioGRID]. Second paper is abstract only. Four review-only rows not shown.","key_references":[{"PMID":"23345436","why":"Slitrk1 and PTPsigma cell aggregation"},{"PMID":"29934346","why":"PTPsigma D2 required for Slitrk1 synapse induction"}],"covers":["LR001989","LR005318"]},"LR001998":{"pair":"SLURP1 -> CHRNA7","headline":"SLURP1 is described as an endogenous CHRNA7 ligand with anti-malignant, CHRNA7-dependent effects in pancreatic cancer cells; binding itself is not directly shown here.","interaction_type":"functional only","direction_and_effect":"SLURP1 acts as an antagonist of nicotine in effect: SLURP1 (anti-malignant, CHRNA7-dependent) and nicotine (pro-malignant, CHRNA7-independent) had opposing activities without reciprocally interfering with receptor binding or downstream signalling, resembling functional antagonism [PMID:29545933].","molecular_requirements":"Not reported in our evidence beyond CHRNA7 itself. The paper notes human-specific CHRFAM7A duplicon receptors can also bind SLURP1 and nicotine with possibly different downstream consequences [PMID:29545933].","affinity_potency":[],"species_and_systems":"Human: patient sera and tissue, and COLO357 and PANC-1 pancreatic cancer cell cultures with high CHRNA7 [PMID:29545933].","localisation_and_range":"SLURP1 is flagged secreted [flag]. The authors hypothesize extrapancreatic SLURP1 reaches pancreatic CHRNA7 through the circulation in an endocrine fashion; serum SLURP1 was 23 +/- 4 ng/ml in healthy donors by one ELISA [PMID:29545933]. Pancreatic tissue was not a source of SLURP1.","caveats":"The curated evidence sentence is background text, and the abstract-level read does not show a binding assay. The paper's own functional work is on cancer cells, and the SLURP1 effect is described as CHRNA7-dependent. Two serum ELISAs disagreed on SLURP1 values [PMID:29545933]. The IntAct record cites a different paper (PMID 26905431) for an affinity chromatography interaction [DB:IntAct].","key_references":[{"PMID":"29545933","why":"Describes SLURP1 as CHRNA7-dependent anti-malignant factor in pancreatic cancer cells"}],"covers":["LR001998"]},"LR002001":{"pair":"SOSTDC1 -> LRP4","headline":"Wise (SOSTDC1) binding to LRP4 is shown in mouse tooth work with in vitro pull-downs; one paper, full text read.","interaction_type":"direct binding","direction_and_effect":"Lrp4 binds the secreted Bmp antagonist Wise, and the interaction modulates Wnt activity in epithelial cells [PMID:19116665]. Net effect is modulatory; a receptor-activating or blocking role is not stated in our evidence.","molecular_requirements":"Not reported in our evidence beyond Lrp4 ectodomain and Wise being sufficient for binding in the assays.","affinity_potency":[],"species_and_systems":"Mouse tooth development; binding tested in HEK293A cells expressing LRP4 and in a cell-free assay with LRP4 ectodomain-Fc, where Wise but not AP or RSpondin2 bound [PMID:19116665]. Mouse Lrp4 and Wise mutants share tooth phenotypes. Human pair is ortholog-inferred.","localisation_and_range":"Wise is secreted from mesenchyme and Lrp4 is on epithelial cells, so paracrine [PMID:19116665]; ligand secreted flag [flag].","caveats":"Single paper; no affinity reported. No database records.","key_references":[{"PMID":"19116665","why":"Wise binds Lrp4 in cell and cell-free assays; mouse tooth"}],"covers":["LR002001","LR005329"]},"LR004797":{"pair":"SPON2 -> ITGAM","headline":"Mindin binds Mac-1 (alphaM integrin) directly, with radiolabelled binding and alphaM-I domain mapping; two papers.","interaction_type":"direct binding","direction_and_effect":"Neutrophil adhesion to mindin was blocked by anti-integrin alphaM antibodies [PMID:16105980]. 131I-labelled mindin binds Mac-1 (CD11b/CD18) via the F-spondin fragment to the alphaM-I domain; blocking the alphaM-I domain blocked mindin-induced phagocytosis, and mindin activates Syk/MAPK signalling [PMID:30869196]. Agonist.","molecular_requirements":"Mac-1 (alphaM with beta2, CD11b/CD18); the FS fragment of mindin binds the alphaM-I domain [PMID:30869196].","affinity_potency":[],"species_and_systems":"Human neutrophils and HEK-293 cells [PMID:16105980]; mouse peritoneal macrophages with CRISPR-Cas9 mindin-deficient mice [PMID:30869196]. Human pair ortholog-inferred.","localisation_and_range":"Mindin is an extracellular matrix protein [flag]; also binds bacteria directly [PMID:30869196].","caveats":"Abstracts only. No affinity value in our evidence. No database records.","key_references":[{"PMID":"30869196","why":"131I-mindin binds Mac-1 alphaM-I domain; phagocytosis"},{"PMID":"16105980","why":"Neutrophil adhesion to mindin blocked by anti-alphaM"}],"covers":["LR001402","LR004797"]},"LR002010":{"pair":"SPP1 -> ITGB5","headline":"Osteopontin binds integrin alphavbeta5 in adhesion assays; two abstract-level papers support it, one with a stated affinity.","interaction_type":"direct binding","direction_and_effect":"Cells adhere to osteopontin through alphavbeta5 when beta5 is transfected [PMID:7592829]; alphavbeta5 binds the RGD site and is additionally sensitive to mutation of two aspartic acid residues upstream [PMID:16005200]. Effect direction not reported in our evidence.","molecular_requirements":"alphavbeta5 heterodimer; RGD site required; thrombin cleavage not required for optimal adhesion [PMID:16005200]. Divalent cations regulate binding, with highest affinity in Mn2+; Ca2+ does not support it [PMID:7592829].","affinity_potency":[{"value":"affinity 48 nM (Mn2+)","assay":"cell adhesion to GST-osteopontin","system":"HEK293 cells transfected with beta5","cite":"PMID:7592829"}],"species_and_systems":"Human recombinant GST-OPN and HEK293 cells [PMID:7592829]; species unspecified in the second paper [PMID:16005200].","localisation_and_range":"SPP1 is flagged secreted [flag]; OPN is an extracellular matrix protein [PMID:7592829].","caveats":"Both papers read as abstracts only. BioGRID lists a reconstituted complex [DB:BioGRID]. The mouse pair is ortholog-inferred. One further paper judged abstract-insufficient.","key_references":[{"PMID":"7592829","why":"alphavbeta5-mediated adhesion, 48 nM"},{"PMID":"16005200","why":"RGD and upstream aspartate requirements"}],"covers":["LR002010","LR005338"]},"LR006579":{"pair":"TGM2 -> ITGA5","headline":"G-361 melanoma cell adhesion to tTG uses alpha5beta1; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"G-361 cells use alpha(9)beta(1) and alpha(5)beta(1) to adhere to tTG [PMID:10816592]. The assay used blocking antibodies [PMID:10816592].","molecular_requirements":"Functional receptor is alpha5beta1, so ITGB1 is also needed [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human G-361 melanoma cells [PMID:10816592]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; adhesion to tTG as substrate [PMID:10816592].","caveats":"Cell adhesion only, abstract-level read, no direct binding. BioGRID records are for ITGB1-TGM2, not ITGA5 [DB:BioGRID].","key_references":[{"PMID":"10816592","why":"G-361 adhesion to tTG via alpha5beta1 and alpha9beta1"}],"covers":["LR003378","LR006579"]},"LR004869":{"pair":"THBS2 -> ITGA6","headline":"Alpha6beta1 mediates adhesion and chemotaxis of cells to the THBS2 N-terminal region; abstract only.","interaction_type":"functional only","direction_and_effect":"Alpha6beta1 mediates adhesion of human microvascular endothelial and HT-1080 cells to immobilised recombinant N-terminal regions of TSP-1 and TSP-2, and chemotaxis to them [PMID:12909644].","molecular_requirements":"The N-terminal pentraxin module carries the site; alpha6beta1 heterodimer [PMID:12909644].","affinity_potency":[],"species_and_systems":"Human microvascular endothelial cells and HT-1080 fibrosarcoma cells with recombinant protein [PMID:12909644].","localisation_and_range":"THBS2 flagged secreted; used as immobilised substrate [flag].","caveats":"Abstract only; adhesion assays rather than direct binding, despite the direct_binding label. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"12909644","why":"alpha6beta1 recognises N-terminal modules of TSP-1 and TSP-2"}],"covers":["LR001474","LR004869"]},"LR006588":{"pair":"THBS4 -> ITGA5","headline":"THBS4 binds ITGA5 by immunoprecipitation in a hepatocellular carcinoma study; browser-read quote pending spot-check.","interaction_type":"direct binding","direction_and_effect":"Immunoprecipitation confirmed that THBS4 can bind ITGB1, ITGB5 and ITGA5 [PMID:32567740].","molecular_requirements":"Pairs with beta integrins ITGB1 and ITGB5 in the same study [PMID:32567740].","affinity_potency":[],"species_and_systems":"Human HCC cells; mouse pair ortholog-inferred [PMID:32567740].","localisation_and_range":"THBS4 flagged secreted [flag].","caveats":"The quote is browser-read and unverified; IntAct anti-bait co-IP records exist [DB:IntAct].","key_references":[{"PMID":"32567740","why":"THBS4 co-IP with ITGB1, ITGB5, ITGA5 in HCC"}],"covers":["LR003387","LR006588"]},"LR004878":{"pair":"TNC -> EGFR","headline":"Tenascin-C EGF-like repeats act as low-affinity agonist ligands of EGFR in human/rodent-derived cell assays; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Select EGF-like repeats of tenascin-C elicited EGFR autophosphorylation and mitogenesis in an EGFR-dependent manner, and activated ERK MAP kinase [PMID:11470832]. Activity was lost in cells expressing a kinase-inactive EGFR [PMID:11470832].","molecular_requirements":"The active ligand is the EGF-like repeats within tenascin-C, not the whole protein; micromolar concentrations were needed, and bead-tethered presentation (mimicking the hexabrachion) raised avidity [PMID:11470832].","affinity_potency":[{"value":"micromolar concentrations (1\u20134 uM) of repeat proteins","assay":"mitogenesis / EGFR autophosphorylation, not a Kd","system":"NR6 cells","cite":"PMID:11470832"}],"species_and_systems":"Experiments used human ligand and human receptor per the curator record; NR6 cells expressing wild-type or kinase-dead EGFR were used [PMID:11470832]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Only one paper, assessed with abstract plus excerpts. Activity was weak: EGF-like repeats gave EGFR phosphorylation small compared with EGF or Y13G (about 2 nM and about 0.1 uM Kd for those reference ligands) [PMID:11470832]. No Kd for the repeats is given [PMID:11470832].","key_references":[{"PMID":"11470832","why":"EGF-like repeats of tenascin-C activate EGFR; binding by immunofluorescence and cross-linking"}],"covers":["LR001483","LR004878"]},"LR004887":{"pair":"TNFSF11 -> TNFRSF11A","headline":"RANKL activates RANK, the core osteoclast axis; evidence here is a mouse RANKL structure, a human identification paper and database records.","interaction_type":"direct binding","direction_and_effect":"RANKL was isolated by expression screening and augments dendritic cell stimulation of naive T-cell proliferation and survival of RANK+ T cells [PMID:9367155]. Mutating surface loops of RANKL modulates RANK activation in in vitro osteoclastogenesis [PMID:11581298]. Effect: agonist.","molecular_requirements":"RANKL is a homotrimer; three RANK molecules bind a RANKL trimer in Reactome [PMID:11581298][DB:Reactome]. Complex formation increases with RANKL [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse RANKL crystal structure at 2.6 A [PMID:11581298]; human cells and proteins [PMID:9367155]. IntAct pull down and surface plasmon resonance [DB:IntAct].","localisation_and_range":"RANKL is flagged secreted and transmembrane, so soluble and membrane forms may act [flag].","caveats":"The structure solves RANKL alone, not the complex; both papers were read as abstracts. The GtoPdb record has no type or affinity [DB:GtoPdb].","key_references":[{"PMID":"9367155","why":"Identification of RANK and RANKL"},{"PMID":"11581298","why":"Structure of mouse RANKL and loop mutagenesis"}],"covers":["LR001496","LR004887"]},"LR008397":{"pair":"TNFSF13 -> SDC2","headline":"Single abstract-only paper shows APRIL binds heparan sulfate proteoglycans generally; syndecan-2 is not named, so SDC2 is unconfirmed.","interaction_type":"functional only","direction_and_effect":"APRIL binds heparan sulfate proteoglycans (HSPG) on tumor cell surfaces through the heparan sulfate side chains, inhibited by heparin; HSPG binding is crucial for tumor growth-promoting activity but not T-cell proliferation [PMID:15846369].","molecular_requirements":"HSPG binding needs a lysine motif outside the TNF fold; BCMA and HSPG bind APRIL simultaneously [PMID:15846369]. Whether HSPG is itself the receptor or presents APRIL to another receptor is unresolved [PMID:15846369].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, tumor cells; abstract only [PMID:15846369].","localisation_and_range":"APRIL is flagged secreted and SDC2 a transmembrane receptor [flag].","caveats":"The paper does not name syndecan-2; the SDC2 assignment is not directly supported. No database records. Abstract only.","key_references":[{"PMID":"15846369","why":"APRIL binds cell-surface HSPG (class-level, not SDC2-specific)"}],"covers":["LR008397"]},"LR004896":{"pair":"TNFSF14 -> LTBR","headline":"LIGHT binds LTBR; one abstract-only mutagenesis paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Point mutations in LIGHT altered binding to LTbetaR and HveA; a HveA-selective mutant was inactive for cell death, isolating the LTbetaR-dependent pathway, with TRAF3 recruitment [PMID:10799510].","molecular_requirements":"LTBR also binds the heterotrimeric lymphotoxin; Reactome lists a 3xLTBR:lymphotoxin,TNFSF14 trimer complex [DB:Reactome][DB:UniProt].","affinity_potency":[],"species_and_systems":"Reconstituted complex in BioGRID [DB:BioGRID]; species of the paper not stated in our evidence beyond human annotation; mouse pair is orthology-projected.","localisation_and_range":"LIGHT flagged secreted and transmembrane; LTBR transmembrane [flag].","caveats":"Abstract only; two other papers abstract_insufficient. Also IntAct yeast display [DB:IntAct] and GtoPdb [DB:GtoPdb].","key_references":[{"PMID":"10799510","why":"LIGHT residues mapped for LTbetaR binding"}],"covers":["LR001506","LR004896"]},"LR004959":{"pair":"VWF -> SELP","headline":"P-selectin's lumenal domain binds the D'-D3 domains of VWF; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Coexpression mapping in HEK293 cells and conventional co-immunoprecipitation indicate the lumenal domain of P-selectin interacts with the D'-D3 domains of VWF [PMID:16418330]. Anchoring of VWF strings is suggested in the abstract.","molecular_requirements":"VWF D'-D3 and P-selectin lumenal domain are required [PMID:16418330].","affinity_potency":[],"species_and_systems":"Human proteins coexpressed in HEK293 cells, which form Weibel-Palade-body-like structures [PMID:16418330]. Mouse pair is ortholog-inferred.","localisation_and_range":"P-selectin is flagged transmembrane [flag]; interaction occurs in Weibel-Palade bodies and at the endothelial surface [PMID:16418330].","caveats":"Abstract-only read. No affinity; interaction may be assisted by the cellular context.","key_references":[{"PMID":"16418330","why":"D'-D3 of VWF interacts with P-selectin lumenal domain"}],"covers":["LR001570","LR004959"]},"LR004968":{"pair":"WNT1 -> RYK","headline":"WNT1 binds RYK in co-IP and AP-fusion assays; RYK acts with Frizzled, supported by two papers.","interaction_type":"direct binding","direction_and_effect":"Wnt-1 and Wnt-3a bound Ryk in co-IP; Ryk siRNA abolished Wnt-1-induced TCF-luciferase, and Ryk acts as a coreceptor with Frizzled [PMID:15454084]. Wnt1 binds Ryk in a second paper, where Wnts repel corticospinal axons via Ryk [PMID:16116452].","molecular_requirements":"A ternary complex of Ryk, Wnt-1 and Frizzled-8-CRD-Fc was reported [PMID:15454084], so Frizzled is a partner.","affinity_potency":[{"value":"Kd 7.89 nM","assay":"AP-fusion binding on COS cells (curator note; ligand not specified)","system":"COS cells","cite":"PMID:16116452"}],"species_and_systems":"Human 293T cells [PMID:15454084]; mouse spinal-cord axon assays, browser-read [PMID:16116452].","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"The second paper's quote is browser-read and unverified; its Kd 7.89 nM is recorded in a curator note with AP-fusion binding on COS cells, and the ligand it applies to is not stated.","key_references":[{"PMID":"15454084","why":"Ryk binds Wnt-1; coreceptor with Frizzled"},{"PMID":"16116452","why":"Wnt1 binds Ryk; axon repulsion"}],"covers":["LR001579","LR004968"]},"LR010998":{"pair":"WNT10B -> FZD5:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173]. UniProt states FZD5 in vitro activates WNT10B signalling (by similarity) [DB:UniProt Q13467].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending. A UniProt record also states that FZD5 in vitro activates WNT2, WNT10B and WNT5A signalling, 'By similarity' [DB:UniProt], so that is inferred, not direct.","key_references":[],"covers":["LR010998"]},"LR006669":{"pair":"WNT10B -> LRP5","headline":"No confirmed paper; supported only by an IntAct co-immunoprecipitation record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Whether Frizzled is also required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"The mouse entry is not ortholog-inferred and the human entry is; the experimental species of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand flagged secreted, LRP5 flagged receptor and transmembrane [flag].","caveats":"Two papers were judged abstract-insufficient, so none confirms the pair.","key_references":[],"covers":["LR003469","LR006669"]},"LR006687":{"pair":"WNT3 -> LRP5","headline":"Zebrafish study using fluorescence cross-correlation reports that Lrp5 is required for Wnt3-Fzd1 binding; direct Wnt3-LRP5 binding is untested.","interaction_type":"functional only","direction_and_effect":"Lrp5 is required for the Wnt3-Fzd1 interaction in a fluorescence cross-correlation assay [PMID:33236989]; the authors state that the Kd for Wnt3-LRP5 remains to be measured.","molecular_requirements":"Lrp5 acts as an essential co-receptor component for Wnt3-Fzd1 binding [PMID:33236989].","affinity_potency":[],"species_and_systems":"Zebrafish brain in vivo; the dossier labels species human, so pair species and experimental species differ. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Wnt3 spreads extracellularly and interacts with heparan sulfate proteoglycans, supporting a diffusive paracrine range [PMID:33236989].","caveats":"The paper determined Wnt3-Fzd1 affinity but no value is in our dossier. The pair as listed (WNT3 -> LRP5) is not itself shown to bind; the evidence is Lrp5 dependence of Wnt3-Fzd1 binding.","key_references":[{"PMID":"33236989","why":"Lrp5 required for Wnt3-Fzd1 interaction in zebrafish brain"}],"covers":["LR003487","LR006687"]},"LR004986":{"pair":"WNT3 -> LRP6","headline":"WNT3 is functionally grouped with Wnt3a-class proteins that depend on the LRP6 third propeller, from antibody blockade only.","interaction_type":"functional only","direction_and_effect":"Co-receptor role: Wnt3a-class anti-LRP6 antibodies, which bind the third propeller, block growth of MMTV-Wnt3 xenografts in vivo [PMID:20713706].","molecular_requirements":"The third propeller of LRP6 is implicated for Wnt3a-class proteins; Wnt1-class proteins use the first propeller [PMID:20713706].","affinity_potency":[],"species_and_systems":"MMTV-Wnt3 tumour xenografts in vivo; species labelled human [PMID:20713706]. Abstract only. IntAct has one surface plasmon resonance record for O75581-P56703 [DB:IntAct].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Evidence is indirect antibody blockade; direct WNT3-LRP6 binding is not reported in the abstract. The listed IntAct pmid is 31036956, not in our papers.","key_references":[{"PMID":"20713706","why":"Anti-LRP6 antibody classes block Wnt3 xenografts"}],"covers":["LR001597","LR004986"]},"LR004977":{"pair":"WNT3A -> FZD6","headline":"WNT3A acts on FZD6 in functional assays; two of three papers are indirect and one is a disease-genetics study.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-3A, among other WNTs, changed FZD6 surface mobility in FRAP, agonist effect [PMID:24873871]. Cells with a FZD6 nonsense mutation responded aberrantly to WNT-3A [PMID:21665003]. GtoPdb lists an Agonist interaction [DB:GtoPdb].","molecular_requirements":"Reported effects are on FZD6 alone; coreceptor requirement is not reported in our evidence. In PMID:24873871 FZD6 mobility effects relate to putative precoupling of Gi/o proteins.","affinity_potency":[],"species_and_systems":"Human FZD6-GFP in HEK293T/17 cells [PMID:24873871]; human fibroblasts and Fzd6-/- mice [PMID:21665003]. The mouse pair is ortholog-inferred.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"The curated direct_binding label for PMID:30594556 comes from a study where SMOC-2 interacted with Fzd6 and LRP6 and enhanced Wnt3a-receptor interaction; it was read as abstract only. PMID:21665003 was read as abstract only and is a genetic study. No affinity reported.","key_references":[{"PMID":"24873871","why":"WNT-3A changed FZD6 mobility in FRAP"},{"PMID":"21665003","why":"FZD6 mutant fibroblasts respond aberrantly to WNT-3A"},{"PMID":"30594556","why":"SMOC-2 enhanced Wnt3a-Fzd6 interaction"}],"covers":["LR001588","LR004977"]},"LR006696":{"pair":"WNT3A -> PTK7","headline":"PTK7 co-precipitates Wnt3a but inhibits canonical Wnt signalling; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PTK7/Otk co-precipitates canonical Wnt3a but inhibits rather than activates canonical Wnt activity; loss of PTK7 activates it [PMID:21772251]. Effect is antagonist.","molecular_requirements":"Epistasis places PTK7 at the level of the Frizzled receptor [PMID:21772251].","affinity_potency":[],"species_and_systems":"Co-precipitation plus Xenopus, Drosophila and luciferase reporter assays [PMID:21772251]. Species of the co-IP proteins are not stated beyond the curator's human label.","localisation_and_range":"PTK7 flagged both secreted and receptor [flag]; a transmembrane receptor per the paper [PMID:21772251].","caveats":"Abstract only; co-precipitation does not prove direct binding. The authors propose PTK7 diverts Wnt into non-canonical signalling.","key_references":[{"PMID":"21772251","why":"PTK7 co-precipitates Wnt3a and inhibits canonical signalling"}],"covers":["LR003496","LR006696"]},"LR007677":{"pair":"WNT5A -> FZD10:LRP6","headline":"No paper-level evidence for WNT5A with the FZD10:LRP6 complex; only database records on single chains.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no confirmed paper for this complex. BioGRID records an Affinity Capture-Western for LRP6 - WNT5A [DB:BioGRID] (PMID 19910923).","molecular_requirements":"The complex combines FZD10 and LRP6; the database records concern individual chains, not the assembled complex. ","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone. Curators judged only review-only or abstract-insufficient papers, with none confirmed. A single-chain record does not show that both subunits are needed.","key_references":[],"covers":["LR007677"]},"LR004995":{"pair":"WNT5A -> FZD7","headline":"WNT5A binds the FZD7 CRD only weakly in BLI; Xenopus data show a functional interaction; thin evidence.","interaction_type":"conflicting","direction_and_effect":"Xfz7 interacts with Xwnt5A to activate the beta-catenin pathway in Xenopus [PMID:10990458]. WNT-5A showed weak binding to the FZD7 CRD [PMID:25605717].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins for BLI [PMID:25605717]; Xenopus for the pathway study [PMID:10990458]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The binding paper reports only weak binding with no KD given in the quoted sentence, and its quote is an unverified browser read. The pathway paper is an abstract read. Reactome and IntAct list WNT5:FZD7 [DB:Reactome][DB:IntAct], but the IntAct records are for another protein pair (O75084-P41221).","key_references":[{"PMID":"25605717","why":"WNT-5A weak binding to FZD7 CRD"},{"PMID":"10990458","why":"Xfz7 and Xwnt5A activate beta-catenin signalling"}],"covers":["LR001606","LR004995"]},"LR007956":{"pair":"CD47 -> SIRPB1:TYROBP","headline":"Computational prediction only: one abstract-level bioinformatics paper proposes SIRPB1 as a CD47 partner; no experimental binding shown.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. The one paper (hepatocellular carcinoma multi-omics) used a PPI network plus structural bioinformatics to name SIRPG and SIRPB1 as high-probability direct CD47 partners [PMID:41587711].","molecular_requirements":"The receptor is a SIRPB1:TYROBP complex, but the paper names only SIRPB1; whether TYROBP is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Computational analysis in HCC (hepatocellular carcinoma) data; no wet-lab species reported [PMID:41587711]. Pair is human.","localisation_and_range":"CD47 is annotated as transmembrane and not secreted [flag], suggesting contact-dependent signalling.","caveats":"Only one paper, read as abstract only, and the assay class is computational. No binding or functional test of this pair. The paper's focus is the CD47-SIRP-alpha axis.","key_references":[{"PMID":"41587711","why":"Bioinformatic prediction of SIRPB1 as a direct CD47 partner in HCC."}],"covers":["LR007956"]}};